quests[26216] = { id = 26216, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stoleways", objectives = "You will be able to choose one of these rewards:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26217] = { id = 26217, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Overboard" }
quests[26218] = { id = 26218, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Long Shot" }
quests[26219] = { id = 26219, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Full Circle", description = "We've located the beast that destroyed our ships. It makes its lair in Darkbreak Cove, a giant underwater cavern bordering the abyss.\n\nThis time we're ready. The gnomes have been engineering a beauty for us back at Stormwind, and it's packing firepower that'll make that fiend wet itself.\n\nWhen the Pincer X2 pulls up to dock beside the ship, make your way on board and help out however you can. We'll be right behind you.", completion = "Vell done, Private {name}.\n\nThe cavern is ours, but the beast escaped. Should it raise it's ugly head again, ve vill make with blastink it out of the vater.", objectives = "Board the Pincer X2 from Voldrin's Hold and aid in securing Darkbreak Cove.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26220] = { id = 26220, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Everything Is Better with Bacon", description = "Feeding a hungry orc army is never an easy task.  Luckily for us, we have a good supply of mature swine meat from the pig farms and surrounding areas south of Orgrimmar.  Do me a favor and slaughter some of those pigs for their delicious belly meat.  I will slice it up and make bacon for the troops' breakfast.", progress = "Have you finished slaughtering the swine?", completion = "Good work, {name}.  These will do nicely.", objectives = "Slaughter Mature Swine south of Orgrimmar and bring me back 6 of their Swine Bellies. I will be waiting for you here in The Drag.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26221] = { id = 26221, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Full Circle", description = "We've located the beast that destroyed our ships. It makes its lair in Tenebrous Cavern, a giant underwater cave bordering the Abyssal Breach.\n\nThis time we're ready. The goblins have been proving their worth by making a vicious machine for us back at Bilgewater Harbor, and it's packing firepower that'll make that fiend wet itself.\n\nWhen the Verne pulls up to dock beside the ship, make your way on board and find a way to make yourself useful. We'll be right behind you.", completion = "Well done, {class}.\n\nThat slippery beast got away! I'll be making a few upgrades. It won't be so lucky next time.", objectives = "Board the Verne from The Stygian Bounty and aid in securing Tenebrous Cavern.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26222] = { id = 26222, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scrounging for Parts", description = "There's just too much to do around here, and too few gnomes on their feet to help! The high tinker has asked me to start converting some of our old bots and parts from Operation: Gnomeregan. I hope to have a new line of multi-bots ready for a field test soon!\n\nI don't suppose you'd have some time to help, do you? There are all kinds of parts scattered around. Pick up anything you find and bring it back to me. You never know what could turn out to be useful!", progress = "Did you get those parts?", completion = "These are fantastic! Let's see what we can put together. Would you be interested in testing out the prototype once I'm done?", objectives = "Bring 7 Spare Parts to Engineer Grindspark in New Tinkertown.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26223] = { id = 26223, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stalking the Stalkers", description = "Many brave trolls have been lost to the harsh wilds of the Hinterlands, {race}. The Silvermane wolves are one of the biggest threats to our hunters. They lay in wait, hiding amongst the bushes and landscape, then strike out when the opportunity presents itself.\n\nThis type of ferocity will not go unchecked!\n\nYou must think like the Silvermane. Stalk the stalkers! Slay them all!", completion = "A job well done, {race}. The Revantusk thank you for your contribution.", objectives = "Kill 8 Silvermane Stalkers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26224] = { id = 26224, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunt the Savages", description = "Among the more ornery of the wildlife of the Hinterlands are the savage owlbeasts. Many a good Revantusk warrior has been lost to the ferocious claws and beak of the beasts.\n\nKill every savage owlbeast you see, {race}. Return to me when you can stand no more bloodshed. Your contribution will then be weighed, measured, and judged.", completion = "You have proven a worthy ally to the Revantusk, {name}. Well done.", objectives = "Kill 10 Savage Owlbeasts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26225] = { id = 26225, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pupellyverbos Port", description = "You there! Did you know that strewn across the northern beach are tens, if not hundreds, of bottles of fine wine?\n\n...well, now you do!\n\nI'd be out there gathering them by the armload, if those turtles weren't out to get me. They crave my blood, I swear.\n\nSo I'll pay you then. Bring me 12 bottles of Pupellyverbos Port and I'll \"purchase\" it from you, {class}.", progress = "Do you have 12 bottles? I know how to count, you know!", completion = "Perfect! I don't know where I'd get this stuff if it wasn't for drunk humans repeatedly crashing their ships.\n\nNormally I'd settle down and get ready to haggle with you for an hour, but you're in luck; I'm too eager to crack these open. Cheers!", objectives = "Collect 12 bottles of Pupellyverbos Port.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26226] = { id = 26226, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crawfish Creole", description = "There are a number of small lakes scattered around Orgrimmar.  These lakes fill up with crawfish every year.  That's where you come in, {name}.  I need you to catch some of those delicious crustaceans and return to me when you are done.  Assuming your catch is successful, our Horde army will feast tonight.", progress = "Were you able to dig up some crayfish?", completion = "Ugh, I never liked cooking these slimy things.  Thanks for the help {name}.", objectives = "Catch 10 Muddy Crawfish in Orgrimmar. Deliver the crustaceans to Marogg when you are done.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26227] = { id = 26227, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Careful, This Fruit Bites Back", description = "Sometimes the troops want something sweet to eat.  I don't always give them what they want but this time, I am going to make an exception.  I am sure you have seen the local cactus that grows here in Orgrimmar.  These cactus produce a tasty treat called prickly pear fruit.  The trouble is the fruit are covered in spines!  Watch your hands and bring me back a handful of that fruit.", progress = "Were you able to find enough fruit?", completion = "Let me see your hands... Aha!  Your not any better at collecting these wretched things than I am!", objectives = "Retrieve 8 pieces of Prickly Pear Fruit. Deliver the fruit to Marogg in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26228] = { id = 26228, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Livin' the Life", description = "Listen, I really shouldn't be talkin' to you, but I owe Horatio a favor or two. I don't really know nothin' about what happened to the Furlbrows, but I might be able to point you in the right direction.\n\n<Lou hands you a large crate.>\n\nThat crate used to be my home before I struck it rich. Now I'm livin' the life every hobo dreams of!\n\nRight, so you take that there livin' crate and head to the Jangolode Mine, southwest of here. Head to the back of the mine and once there, hide in the crate.", completion = "<Lou puts his hands to his ears and starts talking loudly.>\n\nSTOP! STOP! STOP! I don't wanna hear it! I don't wanna know and I don't care! That kind of information is liable to get you killed 'round these parts.\n\nI got one more bit of information for you and then we're done!", objectives = "Use Two-Shoed Lou's Old House at the back of the Jangolode Mine in Westfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26229] = { id = 26229, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "\"I TAKE Candle!\"", description = "Back before those damned kobolds gave me a permanent limp I used to be William Pestle's number one candle supplier. Hell, I even came up with the line \"I TAKE CANDLE!\" Yea, that was me. Kobold would say \"You no take candle!\" and I'd just respond \"I TAKE CANDLE!\" and then bash their brains in!\n\n<Jimb drifts off for a second.>\n\nGood times... The best times.\n\nNow? Can't even use the bathroom without assistance. You want to help me? Kill me some kobolds. You'll find a good load of 'em in the nearby mine.", progress = "I just want those kobolds dead. Dead!", completion = "Oh SWEET justice! Killin' those kobolds won't make me walk like a normal person and it sure won't get me a job, but damn does it feel good.\n\n<Jimb reaches into a crusty old sack.>\n\nHere, I think I got somethin' for you from my kobold huntin' days. Maybe you can put it to good use.", objectives = "Kill 12 Kobold Diggers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26230] = { id = 26230, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feast or Famine", description = "Life in Westfall's hard, <sonny/missy>! Every day is a struggle. We can sometimes go weeks without a decent meal. That's why it's important that we all help each other out. Maybe you can lend a hand, eh? I'm making dirt pies and need some ingredients.\n\nGet me some fresh dirt from the pumpkin patch out front and a bundle of coyote tails. You'll find coyotes wandering around in the wilds of Westfall.\n\nGet moving! We got mouths to feed.", progress = "Dirt pies don't make themselves - usually.", completion = "Just smellin' you comin' got my stomach rumblin'! We're gonna eat like kings tonight!", objectives = "Collect 6 Coyote Tails and 5 handfuls of Fresh Dirt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26231] = { id = 26231, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boarding Party", objectives = "You will be able to choose one of these rewards:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26232] = { id = 26232, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lou's Parting Thoughts", description = "A couple of thugs recently showed up at the farm, causin' all kinds of trouble. I don't know where they came from or who they're working for, but I KNOW they're bad news. I may have overheard 'em talkin' 'bout subjects that might interest you.\n\nIf you're interested, you'll find the thugs back behind the farmhouse. If you get caught or killed, I don't know you. Never seen ya!\n\nGood luck, kid.", completion = "We're dealing with an organization here, rookie. You don't just off the richest bum in Westfall in broad daylight and leave no witnesses. Someone with a lot of power is behind these murders. What have you learned so far?", objectives = "Eavesdrop on the Thugs out behind the farmhouse at Furlbrow's Pumpkin Farm in Westfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26233] = { id = 26233, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stealing From Our Own", description = "As you know, {name}, Garrosh has relegated the trolls of Orgrimmar to the western outskirts of the city.  Fortunately, that means that we have easy access to their supplies.  I am working on a large batch of jambalaya for the infantry and I need as much rice as possible.  Lucky for us, the trolls keep it stored in barrels near their structures.  Retrieve these barrels of Darkspear rice for me and I should be able to finish up.", progress = "Were you able to acquire the rice?", completion = "I see you are a skilled thief as well, {name}.  Don't worry, we will return the rice once we are done... or not.", objectives = "Retrieve 6 Barrels of Darkspear Rice. Deliver the rice to Marogg in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26234] = { id = 26234, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stealing From Our Own", description = "As you know, {name}, Garrosh has relegated the goblins of Orgrimmar to the western outskirts of the city.  Fortunately, that means that we have easy access to their supplies.  I am working on a large batch of jambalaya for the infantry and I need as much rice as possible.  Lucky for us, the goblins keep it stored in barrels near their structures.  Retrieve these barrels of Kezan rice for me and I should be able to finish up.", progress = "Were you able to acquire the rice?", completion = "I see you are a skilled thief as well, {name}.  Don't worry, we will return the rice once we are done... or not.", objectives = "Retrieve 6 Barrels of Kezan Rice. Deliver the rice to Marogg in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26235] = { id = 26235, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Even Thieves Get Hungry", description = "We have had a problem with thieves stealing our infantry rations here in Orgrimmar for the last couple of weeks.  I recently received some intelligence of where these crimes are taking place.  Anywhere you see piles of crates and supplies, there are likely to be thieves nearby.  I need you to hunt these thieves down and recover the stolen rations.  Return to me when you are done.", progress = "Were you able to recover the rations?", completion = "Nice work {name}!  I will see that these rations are returned to the troops immediately.", objectives = "Recover 3 Horde Infantry Rations. Deliver them to Marogg in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26236] = { id = 26236, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shakedown at the Saldean's", description = "So what do we know so far? We need to follow the clues.\n\nOver at the Jansen Stead you found a water-soaked letter and some scraps of red cloth. Here at the Furlbrow's you overheard a conversation between some shadowy figure and an ogre mage. You also got a confession to the murder from a bunch of thugs - whom you then killed.\n\nSomething isn't adding up, rookie.\n\nThere's an old couple, southeast of here, at the Saldean's Farm. Head over there and speak with Farmer Saldean. Find out what he knows.", completion = "Horatio Laine? That man is a scumbag. Dirty as my underwear.\n\nListen, friend, I don't often give out advice like this, but you seem like a good man. GET OUT OF WESTFALL. You're already in way over your head. All you're doing now is putting your neck on the chopping block.", objectives = "Speak with Farmer Saldean at Saldean's Farm in Westfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26237] = { id = 26237, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Times are Tough", description = "Times are tough, <brother/sister>. With the downtrodden masses of Stormwind migrating into Westfall, resources are stretched as thin as they've ever been. The people are restless and in need of help.\n\nOur own farmhouse has been serving as a halfway house for years. Salma does the best that she can to keep our guests alive, but sometimes the watchers get 'em. Watchers are those twisted abominations roaming my fields - a little present left behind by the Defias, before they were driven off. Help us!", completion = "Thank you, brother. You've done Salma and I a great service and I promise that it won't soon be forgotten. I don't have much money, but you're welcome to what I do have.", objectives = "Kill 10 Harvest Watchers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26238] = { id = 26238, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Savage Dwarves", description = "The Horde has done much for us Revantusk, and we're no freeloaders. With the other forest troll tribes pushed back, we're striking out to claim more land in the name of the Horde.\n\nBut now the Wildhammer dwarves are getting in our way. If it's a war they want, it's a war they'll get... and I don't plan to lose a war to creatures half my height.\n\nGet out there and kill me some dwarves.", completion = "That will show the Wildhammer to stay away from our lands!\n\nCrazy dwarves should've stayed in the mountains...", objectives = "Kill 10 Wildhammer Warriors or Wildhammer Shaman.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26239] = { id = 26239, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "<PH>Wildhammer Totems" }
quests[26240] = { id = 26240, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stomp To My Beat", description = "Our warriors are out there fightin' hard to kill them nasty Wildhammer dwarves, so we can be safe back here at the village. It's only right we do what we can to support them.\n\nA good beat's what every troll needs to do his best in a fight. The poundin' rhythm of the drums drivin' you to hit harder, callin' the spirits to watch over you. Take my drums to the battlefield wit' ya. Play 'em for our warriors, and let 'em show the Wildhammer who owns these lands!", completion = "Makes all the difference, doesn't it? That'll teach those dwarves a lesson.", objectives = "Use the Revantusk War Drums on 6 Revantusk Warriors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26241] = { id = 26241, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Westfall Stew", description = "Hello, dear. Welcome to our home. Hmm, you don't look like you're homeless. Have you come to help us? If so, you're just in time! I'm planning dinner for the young ones and need a few simple ingredients.\n\nIf you could get me some okra, goretusk flanks and stringy fleshripper meat I can make my famous Westfall stew! You'll find all of the ingredients near our farm. Just be careful of the harvest watchers. They are merciless killers.", progress = "Food will be ready as soon as I have all of the ingredients! Hurry!", completion = "Bless your heart, dear. These poor orphans haven't had a hot meal in days.\n\nIt looks like we will have enough left over to help feed many more of the homeless of Westfall.", objectives = "Collect 6 Okra, 6 Stringy Fleshripper Meat and 6 Goretusk Flanks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26242] = { id = 26242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deepholm, Plane of Earth" }
quests[26243] = { id = 26243, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The World Pillar", description = "The pillar in this room holds up more than just the Temple of Earth.\n\nThis entire plane of existence will soon collapse into our world if we fail to restore it.\n\nThe time to act will come soon, {name}.  But first you must listen to what I have to tell you.", objectives = "Ask Maruut Stonebinder about the World Pillar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26244] = { id = 26244, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Earth Claims All", description = "We're in the plane of earth, {name}.  Everything is absorbed by the land eventually.\n\nThe Storm's Fury will soon be turned to dust and we won't be able to gain any insight from its remains.\n\nGo and destroy the elementals that are dismantling the ship.  We're only delaying the inevitable, but we need to buy ourselves some time if we're to track down all the pieces of the World Pillar.", completion = "You did what was necessary, {name}.  I can tell you're the sort of {class} I'll get along with well.", objectives = "Destroy 5 Deepstone Elementals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26245] = { id = 26245, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gunship Down", description = "The Archstone was being transported inside a flying Horde gunship called the Storm's Fury.\n\nThe airship crashed south of here and our scrying has revealed the Archstone's no longer on it.\n\nSearch the ship for clues related to what might've happened.", completion = "The clues point to an obvious conclusion.  Too obvious perhaps.", objectives = "Search for clues at the Storm's Fury Wreckage in Deepholm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26246] = { id = 26246, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Captain's Log", description = "<You leaf to the final, interrupted entry.>\n\n...approaching the Temple of Earth at 300 knots and commencing landing maneuvers according to new route.  We've made note of a low pressure system in the north and redrawn our...\n\nBLOOD AND THUNDER!  ALLIANCE SCUM APPROACH!!", completion = "Why would the Alliance attack the Horde just as they're about to deliver a fragment of the World Pillar to us.", objectives = "Bring the Captain's Log to Maruut Stonebinder at the Temple of Earth in Deepholm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26247] = { id = 26247, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diplomacy First", description = "The Earthen Ring is a neutral organization, {name}.  We cannot pick sides in the war between the Horde and the Alliance.\n\nLook around you -- our members come from all backgrounds.  Our mission would be compromised should racial tensions be put above our goal.  Let's try to keep this under wraps until we have more information.\n\nWe must not jump to conclusions just yet.  I'll send you and one of our new members to look for the Alliance gunship.\n\nFind out what you can without dragging us into the conflict.", completion = "Oi, {name}!  I was told I'd have company soon.", objectives = "Meet Stormcaller Mylra aboard the Alliance Gunship.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26248] = { id = 26248, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All Our Friends Are Dead", description = "Something's wrong here, {name}.\n\nThe ship's crew has been slain.  Yet there is no bloodshed or damage to the ship's structure.\n\nThis was not the Horde's doing.\n\nWe will find the answers we seek by speaking to the spirits of the dead.  They have not yet left this world.\n\nTake this totem and place it near the corpses of the fallen.  You will have a few seconds to listen to their last few thoughts.\n\nBeware, however!  There is no telling how the spirits of the dead will react to our prodding.", progress = "The spirits always have something to say to those who will listen.", completion = "We were bound to run into the Twilight's Hammer sooner or later, {name}.  If they're behind this, it's quite likely that the World Pillar fragment is in their possession.", objectives = "Use the Spirit Totem on the corpses of 6 Slain Crew Members.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26249] = { id = 26249, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Admiral's Cabin", description = "It's possible we'll find further clues inside the admiral's cabin. You will find it directly below us.\n\nSee if there are any survivors or information that will lead us closer to the World Pillar fragment.  Be careful, {name}.  Whoever got the crew might still be out there.", completion = "This ship is filled with rats...", objectives = "Look for clues in the admiral's cabin of the Alliance Gunship.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26250] = { id = 26250, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On Second Thought, Take One Prisoner", description = "It's not too late, {name}.  The cultists are probably still here.\n\nGo below decks, find out who's in charge and subdue them.\n\nWe will obtain answers to our questions, one way or another.", completion = "Oi, this was a heavy one!  He nearly broke me gryphon's back!\n\nAre you ready to interrogate the ogre, {name}?", objectives = "Subdue Mor'norokk the Hateful at the Alliance Gunship in Deepholm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26251] = { id = 26251, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Take No Prisoners", description = "It looks like the Twilight's Hammer's still on the ship.  Go below decks and take them out.\n\nBe careful, {name}.  I've a feeling they're not here for a spiritual retreat, if you know what I mean.", completion = "Well done, {name}.  The Twilight's Hammer is an evil that we must fight anywhere we find them.", objectives = "Slay 6 Twilight Saboteurs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26252] = { id = 26252, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heart of the Watcher", description = "You have found what appears to be the heart of a harvest watcher.\n\nFrom the sound being emitted by the device you can tell that it's still fully functional. Perhaps you should return it to Farmer Saldean.", progress = "What have you got there, {name}?", completion = "Is that... Is that the heart of one of the watchers? I've heard stories about using one of these to power up a watcher for personal use. Of course I'm really in no shape to try such things myself.", objectives = "Return the Harvest Watcher Heart to Farmer Saldean at Saldean's Farm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26253] = { id = 26253, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preserve the Evidence" }
quests[26254] = { id = 26254, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Some Spraining to Do", description = "Hop on, {name}.  Let's see what Mr. Ogreface has to say for himself.\n\nDon't be shy, Stormbeak's only ever dropped a passenger a couple of times before.", progress = "Yes, {name}?", completion = "We have our answers, {name}.  Let's report back.", objectives = "Jump on Stormbeak and watch Mor'norokk's interrogation.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26255] = { id = 26255, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Temple of Earth", description = "You must get word back to the others at the temple.  Chances are, the fragment is already getting moved to a more secure location.\n\nTell Maruut what you know.  I'm going to do a little investigating about this Twilight Council in the meantime.", completion = "We must investigate your findings further, but we must not lose track of the fragment.", objectives = "Speak to Maruut Stonebinder at the Temple of Earth in Deepholm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26256] = { id = 26256, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bleed the Bloodshaper", description = "The Twilight's Hammer are wielding foul magic here, {name}.  They animate and energize the remains of Deathwing's blood, so that instead of drying out and disappearing it thrives and becomes more abundant.\n\nTake out one of the bloodshapers, see if they have any clues as to where we can find this \"forgemaster.\"", progress = "We must make haste if we're to rebuild the World Pillar, {name}.", completion = "They're keeping slaves here?  We ought to free them regardless, but perhaps they might also aid us in finding the forgemaster.", objectives = "Obtain the Twilight Orders from one of the Twilight Bloodshapers at Deathwing's Fall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26257] = { id = 26257, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Alive!", description = "From what I've heard, all you really need to do is find a suitable harvest golem and drop in the heart. Once you've done that you should be able to take full control of the creature.\n\nI think there's a whole field of overloaded harvest golems west of here, at the Molsen Farm. Look for the arcs of electricity.\n\nShould you manage to get it working, use the golem to destroy the energized harvest reapers at the old Molsen farm. Those monsters are much more destructive than the ones on our farm.", completion = "It actually worked? That's incredible, {name}. Hopefully that takes care of the harvest golem problem here in Westfall.", objectives = "Use the Harvest Watcher Heart on an Overloaded Harvest Golem and then use the Overloaded Harvest Golem to kill 25 Energized Harvest Reapers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26258] = { id = 26258, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deathwing's Fall", description = "The Twilight's Hammer involvement in the disappearance of the World Pillar fragment makes complete sense.  Let us hope that we can act swiftly enough to recover it.\n\n<Maruut places his hand on your shoulder.>\n\nI've established a spiritual bond with you.  We should be able to communicate while you remain in Deepholm.\n\nGo to Deathwing's Fall to the southeast and investigate the Twilight's Hammer operation there.", completion = "This must be where the world pillar fragment was brought.  Let's have a closer look.", objectives = "Go to Deathwing's Fall in Deepholm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26259] = { id = 26259, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood of the Earthwarder", description = "When Deathwing escaped to Deepholm, his corruption was extreme, but perhaps not yet absolute.\n\nThe cultists at Deathwing's Fall harvest and shape the corrupted blood he left behind into living organisms to draw from their power.\n\nWhat if a trace of the Earthwarder's essence remains?  After all, Neltharion was the aspect of earth before he was the aspect of death.\n\nGather samples from the living blood the cultists have created and we'll see if any trace of the Earthwarder remains.", progress = "You return, {name}.  Did you obtain the blood?", completion = "There is still great power present in his blood, {name}.  I can sense it even now.\n\nYet there is also much corruption.  I am not sure we can salvage the Earthwarder's essence from this.", objectives = "Gather 5 samples of Blood of Neltharion from Living Blood at Deathwing's Fall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26260] = { id = 26260, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Forgemaster's Log", description = "Go to the tower the slave spoke of.  You should find it on the northeastern end of the camp.\n\nIf we can act fast enough we might be able to eavesdrop on the forgemaster's meeting.", completion = "There is an entry for an upcoming meeting at the Upper Silvermarsh.\n\nThis must be where the Forgemaster is.", objectives = "Find the Forgemaster's Log at Deathwing's Fall in Deepholm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26261] = { id = 26261, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Question the Slaves", description = "According to the orders you found, there is a key inside the tent in the southeastern end of Deathwing's Fall.\n\nObtain it and free the slaves in the quarry to the south.", completion = "Let us find this journal.  We're getting close to the World Pillar fragment, I can sense it.", objectives = "Obtain the Twilight Slaver's Key and free 6 Enslaved Miners.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26262] = { id = 26262, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Armaments" }
quests[26263] = { id = 26263, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thornar Thunderclash", description = "We've been trying to take out the commander of the Wildhammer encroaching on our lands, but we've had no luck.\n\nThornar Thunderclash sits in the safety of his command post, his voice booming across the battlefield to rally the dwarves. We're thinking he needs to be quieted.\n\nCut Thornar down and we can clean up the rest of this skirmish with no problem.", completion = "Well done, mon. A fine hero of the Horde you are.", objectives = "Kill Thornar Thunderclash.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26264] = { id = 26264, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What's Left Behind", description = "Most of us have seen the sickly and deranged gnomes suffering from exposure to the poisons and radiation of Gnomeregan. Eventually, they will devolve further, until they become mindless, but mostly harmless, puddles of toxic sludge.\n\nMy research suggests that we may even be able to restore them from this state. Go to the Toxic Airfield to the south, subdue the toxic sludge I told you about, and bring back the possessions of the gnomes they once were.", progress = "Were you able to recover the belongings of any of the irradiated gnomes?", completion = "I can't wait to give this new technology a try! We've lost more gnomes to radiation than we can count. It's time to turn that around!", objectives = "Retrieve 6 Recovered Possessions from Toxic Sludges at the Toxic Airfield.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26265] = { id = 26265, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dealing with the Fallout", description = "Tock Sprysprocket has some crazy theory about these toxic sludges being the last remnants of gnomes, so my men have orders not to engage them for now.\n\nHowever, the Toxic Airfield, just south of us, is teeming with living contamination. They are elementals composed of contaminated water and other toxic materials. Left unchecked, they'll overrun the town. Will you help us dispose of them?", progress = "Were you able to clear away any of the contamination?", completion = "What a relief! Thank you for your help. I hope that gadget Engineer Grindspark was working on helps get the airfield cleaned up permanently.", objectives = "Destroy 6 Living Contaminations at the Toxic Airfield.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26266] = { id = 26266, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hope for the People", description = "About four years ago, in the dead of the night, a little girl walked right into our farmhouse and collapsed on the floor. Nobody had a clue as to her identity. The poor little thing had no recollection of who she was or where she came from - truly a lost soul.\n\nSoon after, we adopted the little girl and named her Hope - for that is what she represented.\n\nShe is now a young lady, caring for the destitute and homeless of Westfall. Take my Westfall stew to her at Sentinel Hill, south of here.", progress = "Good day sir. How may I serve you?", completion = "I smell Westfall stew! Mother sent you!?", objectives = "Take the Westfall Stew to Hope Saldean at Sentinel Hill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26267] = { id = 26267, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skulk Rock Clean-Up", description = "Years ago, there used to be a Horde base deep within Skulk Rock. It's been abandoned since then, but it's still prime territory, worth reclaiming.\n\nThe problem is, it's full of oozes by now. They're nasty things... mindless, corrosive, eat anything they find.\n\nI need someone brave to go to Skulk Rock and get rid of those slimes. Are you brave enough, {name}?", completion = "It's good to see you back... and not missing any limbs, either.", objectives = "Kill 10 Jade Oozes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26268] = { id = 26268, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skulk Rock Supplies", description = "I was at Skulk Rock during the second war. I was young, years before I met my mate, and I still remember the chaos when the Alliance attacked us. We fled with the orcs, without any time to gather our belongings.\n\nIt was all left behind. Skulk Rock is still full of our old supplies. We could use them here at the village... and more importantly, the Wildhammer shouldn't get their filthy hands on them.", progress = "How many crates did you find?", completion = "They're still intact! There's a lot of memories in these crate. Let's see what we've got in the first one...\n\nHey, banana bread! And it's still fresh!\n\nHere, mon, I'll take this and you can pick something else.", objectives = "Collect 5 Ooze-Coated Supply Crates.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26269] = { id = 26269, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Green Hills of Stranglethorn", description = "One page!  I only need one more page!\n\nMaster Nesingwary's novel ran into a bit of an... accident <Barnil shoots an accusing glance over at Spanks>... and we misplaced some of the pages.\n\nI've been asking your fellow adventurers to look for the missing pages, and they've been quite helpful, but one page still eludes me.\n\nI'm sure you're awfully busy with other matters, but while you're out in the jungle, would you mind looking for it?", progress = "Have you found it?  I'd hate to return an almost-finished book back to Hemet.", completion = "You've certainly saved me a heap of trouble, {name}!  I can't thank you enough.  It shouldn't be long now until we see Master Nesingwary's book in libraries throughout the world!\n\nI'll leave a copy of the book right here, if you ever want to take a peek at the finished product.  Thanks again, {name}!", objectives = "Find Page 14 of the Green Hills of Stranglethorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26270] = { id = 26270, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Have Our Thanks", description = "It's been many years since anyone has offered to lend us aid, {name}. Had you not come along, we might not have made it through the coming winter. You have proven yourself to be a selfless individual - a person that we can trust. I only wish we had something of value to offer you.\n\nWhile I have no information to assist you in your crusade to bring the Furlbrow's murderer to justice, perhaps my wife can help. Speak to Salma inside and she will tell you what you need to know before you leave.", completion = "Of course, dear. Our little girl works at Sentinel Hill and is very close with the homeless of Westfall. Perhaps she has overheard something. Before you go, let me wrap up the Westfall Stew and tell you a little bit about our dear little girl.", objectives = "Speak with Salma Saldean at the Saldean's Farm in Westfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26271] = { id = 26271, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feeding the Hungry and the Hopeless", description = "Yes, I heard about the Furlbrow murders. It is very tragic, but such tragedy is a way of life in Westfall. There are many people here who simply no longer have the means or inclination to keep themselves fed. They have given up hope. Do you understand what it means to be left so hopeless as to stop caring about life? We must work together to show them that there is hope. That with the dawning day a better life comes.\n\nTake my mother's Westfall stew and help feed the homeless around Sentinel Hill.", completion = "You have a kind heart, {name}. You have done a good thing, today, and that act will reflect back upon you when judgment day comes.", objectives = "Use the Westfall Stew to feed 20 Homeless People around Sentinel Hill in Westfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26272] = { id = 26272, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rise of the Darkspear", description = "Tha Darkspear tribe have long been victims. Outcasts. We found ourselves fleein' our homes time 'n time again... but dis time, it's not fleein' dat drives us here.\n\nVol'jin has offered us leadership through wisdom, and it has kept us alive dis long. Now dat same wisdom offers portents of a chaotic future for tha Horde unda Garrosh Hellscream.\n\nNo, dis time we not fleein'. Dis time, we are fightin' for a home dat will last.\n\nIt's time to begin ya trainin', {name}. Speak with Voldreka to the east.", completion = "Anotha newblood, eh?\n\nYa actually have an intense look about ya though. Fiery eyes. You might have the makings of a real {class}.\n\nLets not waste anymore time 'den.", objectives = "Meet with Voldreka in the Darkspear Training Grounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26273] = { id = 26273, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Basics: Hitting Things", description = "Alright, mon. We start simple. I need ta know dat you know the basics of the dark arts.\n\nGo thrash dose tiki targets. Take it slowly. Natural-like. I'll watch how you form your casts and we'll go from dere.", progress = "Power stems from dis world and worlds you've not yet seen. Masterin' da power of one ain't gonna be enough ta make it outside of dese trainin' grounds - you gonna need to be pullin ya power from all of dem.", completion = "Not bad, mon. Ya have a deep power in ya spells - you may have a talent for dis.\n\nSome rough edges ta be sure, but we'll get dose ironed out here and I'll teach ya a few new tings as we go.", objectives = "Destroy 6 Tiki Targets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26274] = { id = 26274, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Arts of a Warlock", description = "I tink I have something I should let ya know.\n\nAs ya' get more powahful, yo' gonna staht hearin' da voices - teachin' you new tings, new spells.\n\nGo, get some more experience, 'den come back an show me what ya learned.", completion = "Good work, mon! Dis stuff come easy to ya.", objectives = "Reach Level 3 to Learn Corruption. Practice using Corruption 5 times against a Tiki Target.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26275] = { id = 26275, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Rough Start", description = "Lets put dose skills ta use. I'll start ya off easy, mon.\n\nThere be cats killing our boars. Dat food ain't for sharin'. Dose boars are gonna need ta be alive if ya be wanting food tonight.\n\nDey're all over the island. Bring me some cat pelts.", progress = "I doubt dey too much of a challenge, mon, but they'll still claw up ya ankles if ya don't stay quick footed.", completion = "Dese are some fine pelts, boy. We could make some hefty cloaks outta dese.", objectives = "Retrieve 6 Wildmane Cat Pelts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26276] = { id = 26276, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proving Pit", description = "Ya done quite well for ya'self, {class}. I'm sure I could teach ya a trick or two here and dere, but I not be wastin' ya time on tiki targets no longer.\n\nl put one last trial before ya den, mon. Head over to da provin' pit in the middle of dis area and fight a real baddy - one dat wants ta kill ya back. Just let the jailor by the pit know when ya ready.", progress = "All trolls gotta prove demselves before we let them move past da training grounds.", completion = "Ya handle yerself quite well. Ya gonna be quite powerful some day.", objectives = "Speak to a Darkspear Jailor, then enter the proving pit and kill a Captive Spitescale Scout.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26277] = { id = 26277, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Than Expected", description = "Ya definitely more den expected, mon. I'm sure dere's more important stuff we can be usin' ya talents on now. Ya don't need ta hang out with da newbloods no more.\n\nHead down to da village to da southeast and make yaself known. Lend a hand here and there and I'm sure ya make yer way up to sometin' more prestigious quick enough.", completion = "Ya tha new recruit everyone's talkin' about, eh? Welcome ta tha Darkspear.", objectives = "Report to Vol'jin at Darkspear Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26278] = { id = 26278, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Defense of Grom'gol: Raptor Risk", description = "Throm'ka, {class}!\n\nYour arrival at Grom'gol is timely, indeed.  Our mission to provide a safe chain of supply to Stonard is being hampered by some of the local inhabitants.\n\nI am putting you in charge of eliminating the raptor population outside of Grom'gol, just to the north.  Don't worry about the raptors themselves... those wretched Nesingwary hunters will take care of them.\n\nI want you to destroy their eggs.", completion = "Keep up the good work, {class}.  Hellscream's eyes are upon you.", objectives = "Destroy 12 Lashtail Eggs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26279] = { id = 26279, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Defense of Grom'gol: Ogre Oppression", description = "When we first arrived in this jungle we did not intend to wage war on the local tribes.  Our mission to supply Stonard is of the highest priority.  But complications have arisen.  A local band of ogres has occupied the Mizjah Ruins to the southeast of Grom'gol.  Despite warnings, they continue to ambush our supply caravans.\n\nI am putting you in charge of dealing with these uncooperative ogres.\n\nTravel to the ruins and attempt to drive them from the area.  At the very least it will send a firm message.", completion = "I see you are good for more than simple egg-smashing duty.  Good.  The Horde can use a capable {race} like you.", objectives = "Kill 4 Mosh'ogg Brutes and 4 Mosh'ogg Witch Doctors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26280] = { id = 26280, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Defense of Grom'gol: Murloc Menace", description = "The Murkgill murlocs have been pushed out of the ocean by the Saltscale murlocs, so they make their refuge in the Kal'ai ruins to our northeast.  This was acceptable in the past, but no longer.\n\nSeparated from the sea, the Murkgill have grown restless, and they send their foragers to attack my supply caravans.  Send them a message: this behavior will NOT be tolerated by Hellscream's Horde.", completion = "Excellent work. Hopefully the raids will stop for now.\n\nI have one more task for you, {name}.", objectives = "Slay 15 Murkgill murlocs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26281] = { id = 26281, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Defense of Grom'gol: Trollish Thievery", description = "The trolls leave us well enough alone here in Grom'gol.  Most trolls know that the Horde can easily crush them when angered, and the trolls here in Stranglethorn are no exception.\n\nThe Bloodscalp have been more active lately, however.  As lately as last week, they sent a party into Grom'gol and stole several cases of rations.\n\nStealing food is the most forgivable type of theft, but I still can't let it happen under my watch.  Head north, to the Bal'lal ruins, and return our property.", progress = "Pity has no place under my command.  The trolls can find food elsewhere.  It's a big jungle.", completion = "<Aggro'gosh salutes you.>\n\nThe Horde thanks you, {name}.  Grom'gol is protected, if only for today.", objectives = "Obtain the Grom'gol Rations from the Bal'lal ruins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26282] = { id = 26282, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Favor of Akil'darah" }
quests[26283] = { id = 26283, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prime Slime", description = "I've become very interested in the slimes inhabiting Skulk Rock. No matter how many times they're cleared out, they seem to return, yet it doesn't seem they're capable of reproducing from a single slime.\n\nI think something's growing in there. There's a source where all the slimes come from, and I want to study it. Find this source, and bring me back a sample.", progress = "Well? What did you find?", completion = "Fascinating... How large did you say it was? I wonder if others could be found intact...\n\nThis sample is excellent. I'll be sharing it with my fellow researchers.", objectives = "Collect a Direglob Sample from The Direglob.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26284] = { id = 26284, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missing in Action", description = "Fer a job like this, I normally bring me whole crew o' demolitionists. With some help in settin' up th' powder, th' charges, and th' rest o' th' gear, the job gets done a lot faster.\n\nThose blasted troggs have me men caged all around Frostmane Hold. Now I'm 'ere all alone without th' personnel I need to finish th' job.\n\nYou look like a capable {class}, though. Would you find th' demolitionists th' troggs captured and break them out o' their cages?", completion = "You have me own thanks and th' thanks of th' men you rescued. I've already had th' boys start setting up the gear down inside the cave. It should be ready to go soon.", objectives = "Free 6 Captured Demolitionists from their cages around Frostmane Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26285] = { id = 26285, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get Me Explosives Back!", description = "It's gonna take a lot of powder ta collapse those caves. I don't know whether th' damnable troggs understood that when they stole me supplies and kidnapped me demolitionists! But th' outcome's th' same.\n\nAin't gonna be able ta blow nothin' up until I've got that powder back.\n\nGo south to Frostmane Hold and kill any o' those troggs you find. Any one o' 'em could be carryin' me kegs o' powder.", progress = "Well, did you recover me missing supplies?", completion = "Well, now, that's more like it. We may get around to blowin' up somethin' after all.", objectives = "Recover 7 Stolen Powder Kegs from Rockjaw Bonepickers or Rockjaw Marauders at Frostmane Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26286] = { id = 26286, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Defense of Westfall", description = "After my tour of duty was over in Grizzly Hills, I returned to Westfall, only to find the land in worse condition than when I left.\n\nThe price of our war left thousands of citizens homeless. They now migrate here and squat upon the deserted farmhouses and towns of the region.\n\nTo make matters worse, we are now under attack by the gnolls. The Westfall Brigade needs your help, {name}. Slay the attacking gnolls and recover their orders. Someone is pulling their strings and we need to find out whom!", progress = "Have you recovered the attack orders?", completion = "Helix? I've heard that name before. Recently as a matter of fact, but who is this admiral?", objectives = "Recover the Gnoll Attack Orders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26287] = { id = 26287, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Westfall Brigade", description = "We were once known as the People's Militia. These days, though, we fight under the banner of Stormwind, with the full support of King Anduin Wrynn. Our goals here in Westfall are many: to clean up the mess left behind by the Defias, to expand the reach of the Alliance and to maintain order. So far we are failing on all fronts.\n\nTimes are worse now than when the Defias ran amok. Now with the indigenous gnolls of the region up in arms, we find ourselves backed into a corner. Help us, {name}!", progress = "Defend Sentinel Hill!", completion = "Well done, {name}. You have provided us a temporary reprieve from the onslaught of gnolls, but there is more work to be done.", objectives = "Slay any 12 Riverpaw Gnolls attacking Sentinel Hill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26288] = { id = 26288, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jango Spothide", description = "South of here is an area of Westfall known as the Dust Plains. From what we know the gnolls of the region have made the Dust Plains their unofficial capital. As with any capital, there exists a leader at the heart. If we are to put an end to these attacks, we must track down the gnoll in charge and end him.\n\nVenture forth into the Dust Plains, find the gnoll leader, Jango Spothide, and kill him. Take out any other gnolls that get in your way.", completion = "Excellent work, {name}. It will take the Riverpaw weeks to recover from the blow you just dealt. Please take an item of your choosing as a reward for what you have done.", objectives = "Slay 5 Riverpaw Mystics, 5 Riverpaw Taskmasters and Jango Spothide.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26289] = { id = 26289, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Find Agent Kearnen", description = "SI: 7 has been tracking Helix Gearbreaker since he entered Alliance territory two weeks ago. The letter I received from Mathias Shaw explained that he sent an agent by the name of Kearnen to Westfall to shadow Helix. Find Agent Kearnen and you'll find Helix Gearbreaker.\n\nKearnen came into town for supplies two days ago. She mentioned that she would be near Mortwake's Tower, southeast of here, on the Dust Plains.\n\nGet going, {name}.", completion = "Helix is the one responsible for the gnoll attacks?\n\n<Kearnen nods at the tower.>\n\nHe's inside. He's been there for days. I've just been waiting for an excuse to bust him.", objectives = "Find Agent Kearnen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26290] = { id = 26290, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets of the Tower", description = "Helix has got himself holed up inside Klaven Mortwake's old tower. I won't lie to you, {name}, it's heavily guarded. I count six armed mercenaries just on the outside. There's no way you're getting inside that tower by yourself. Lucky for you, Claire and I are here.\n\n<Kearnen pats her sniper rifle.>\n\nI'll cover your entry.\n\nTake this shrouding potion, you'll need it once you get inside. Use it as soon as you enter the tower and head upstairs. Find out what Helix is hiding up there!", progress = "I won't let you down, {name}.", completion = "What could possibly be going on in Moonbrook? I don't like this one bit, {name}.", objectives = "Enter Mortwake's Tower and find Helix Gearbreaker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26291] = { id = 26291, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Big Trouble in Moonbrook", description = "I'll be filling out my report and heading back to Stormwind shortly. SI: 7 must be informed of the happenings in Westfall. I would recommend you do the same and report back to Gryan.", completion = "Who IS this Shadowy Figure? We have to get to Moonbrook.", objectives = "Report your findings to Marshal Gryan Stoutmantle at Sentinel Hill in Westfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26292] = { id = 26292, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Moonbrook!", description = "We have had a camp near Moonbrook for quite some time now, {name}. One of my best soldiers works the area along with a company of Sentinel Hill troopers. Report to Captain Alpert now and find out if he has any news about the happenings in Moonbrook.\n\nAnother ally of mine is also at the Moonbrook camp. His name is Thoralius. I met Thoralius in Northrend during my time in Valgarde. He is a wise and powerful shaman. Perhaps his abilities could help us solve this mystery.", completion = "The natives are restless, {name}. I don't know what's going on, but homeless activity in this area has quadrupled in the past two days. If I didn't know any better I'd say they were planning something...", objectives = "Report to Captain Alpert at Moonbrook in Westfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26293] = { id = 26293, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Machines of War", description = "Far to the east the \"Worldbreakers\" lay hidden in the Twilight Highlands. We must end their threat and we will do it with the most powerful army ever!\n\nOur new allies, the goblins, are making us new machines of war but I hear that there are problems with the quality. We can't fight with broken war machines. Speak to Foreman Glibbs and make sure our machines are ready for battle.", completion = "Busy now. Go away.\n\nWait, what? Hellscream sent you? What - uh - what can I do for you? Him? Us?", objectives = "Talk to Foreman Glibbs just inside the Orgrimmar Rear Gate in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26294] = { id = 26294, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weapons of Mass Dysfunction", description = "<Glibbs mops sweat from his brow with a greasy handkerchief.>\n\nSaurfang isn't happy with our work? This is very bad. My boys need to step it up.\n\nMaybe you can help set an example. A set of Hellscream Demolishers just rolled off the blocks and are ready for inspection. Give them a thorough going-over, and if you find any problems, give the Chief Engineer a good thrashing. Remind them that the Horde is depending upon them!", progress = "You spoke with the Foreman?\n\nWell?", completion = "<Garrosh laughs.>\n\nInstilled a little discipline in them, did you? Good, good!\n\nEveryone pulls their weight in my Horde, from the smallest peon to the proudest warrior. I tolerate nothing less.\n\nOur preparations for the invasion are almost complete.", objectives = "Inspect Hellscream Demolishers until you find a faulty one, then teach its Chief Engineer a lesson.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26295] = { id = 26295, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Propaganda", description = "We've noticed a rise in violent acts amongst the homeless of the area. Something or someone is getting them all riled up. Now whoever is behind all this is getting more organized. Just recently a group of thugs came through here handing out pamphlets.\n\nEnter Moonbrook and look for evidence. Propaganda, leaflets, whatever... Bring whatever you find back to me. Maybe we can find the source through the writings.", progress = "Any luck?", completion = "V? The only V I know is VanCleef, but he died many years ago.", objectives = "Recover an Informational Pamphlet, Secret Journal, an Issue of the Moonbrook Times and Mysterious Propaganda.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26296] = { id = 26296, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Evidence Collection", description = "The material of this bandana is identical to the material found at the Furlbrow murder scene. You should collect more red bandanas as evidence and return what you find to Captain Alpert.", progress = "Red bandanas?!", completion = "I haven't seen a red bandana in five years. Could this shadowy figure be attempting to reform the Defias Brotherhood?", objectives = "Collect 6 Red Bandanas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26297] = { id = 26297, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dawning of a New Day", description = "It looks like the meeting the shadowy figure spoke of is starting soon. The homeless are starting to mobilize. I need you to attend the rally and gather information, {name}.\n\nGo to the center of Moonbrook and listen in on the rally. Return to me with whatever you find out.", progress = "What happened?", completion = "I could hear the cheers from here. It seems as if we've got a huge problem on our hands, {name}.  We have to discover the identity of this shadowy menace before we enlist the aid of Stormwind. Perhaps there is another way...", objectives = "Gather information from the Moonbrook Rally.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26298] = { id = 26298, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunt for Yenniku", description = "A doom, there is.  A doom on my chief's youngest son, Yenniku.  As is a custom with our people, he was given to the Gurubashi Trolls of Zul'Gurub, but after my tribe, the Darkspear tribe, left with the orc Thrall, poor Yenniku was lost to us.  I was sent from distant Orgrimmar, back to Stranglethorn, to search for my chief's son.\n\nAnd I believe the Bloodscalp tribe has him.\n\nIf you would help me, then hunt the Bloodscalps.  You may find them to the north.  Gather their tusks and return to me.", progress = "{class}.  Show me you have made prey of the Bloodscalp tribe.\n\nShow me your trophies.", completion = "These are good tusks, {name}.  You prove that you have the strength to hunt the Bloodscalps.\n\nAnd that is good, because you are not done hunting them.", objectives = "Obtain 6 Bloodscalp Tusks from Bloodscalp trolls in the Bal'lal Ruins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26299] = { id = 26299, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Headhunting", description = "We must find if Yenniku is dead.\n\nSlay the Bloodscalps of Zuuldaia and take from them their shrunken heads.  You must gather many, many heads, and I will inspect them to make sure Yenniku's head is not among them.\n\nAnd if Yenniku was killed by the Bloodscalps, then may a 600-year curse fall on the spirit of their chief, Gan'zulah!\n\nGo, {name}.  You will find the heads at the ruins of Zuuldaia, along the coast to the north.", progress = "{name}.  I fear for our chief's son.  Do you have the shrunken heads so I may inspect them?", completion = "Thank you, {name}.  I will inspect these heads to ensure poor Yenniku was spared the headhunter's axe.", objectives = "Obtain 25 Shrunken Heads from Bloodscalp trolls at the Zuuldaia Ruins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26300] = { id = 26300, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nezzliok Will Know", description = "Yenniku was not among the heads, and I thank the Great Serpent for it.  But we are no closer to finding him.\n\nWe must know the truth, and I fear that only the Bloodscalp witchdoctor will know it.  He is an enemy of the Darkspear tribe and will not speak freely, so we must force the truth from his dead lips!\n\nBring me the head of Nezzliok the Dire and place it within this cauldron.\n\nHe is deep within Zul'Kunda.  Bring his head...we will then make it talk.", progress = "The greenish broth within the cauldron bubbles.", completion = "You place the head of Nezzliok within the cauldron...", objectives = "Obtain Nezzliok's Head from Nezzliok the Dire in Zul'Kunda.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26301] = { id = 26301, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speaking with Nezzliok", description = "<The head of Nezzliok speaks.>\n\nIt is true.  I know where the child of the Darkspears was taken.  You have bested me and bound my spirit, but I will say nothing without appeasement!\n\nThe Bloodscalps war with the Skullsplitters.  To gain my favor, steal two of their most-prized trophy skulls from the Skullsplitters across the river to the east.  Place them here with us, so that my spirit will have slaves in the Nether.  One skull must be from their trophy pile in Balia'mah, the other from Ziata'jai.", progress = "I await the skulls...", completion = "Yes.  These will serve me well.  When my spirit is freed, I will enter the Nether with some fine servants indeed!\n\nYou are a credit to your {race} clan, and you have appeased me.", objectives = "Obtain a Balia'mah Trophy and a Ziata'jai Trophy from the Skullsplitter ruins in Northern Stranglethorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26302] = { id = 26302, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chasing Yenniku's Fate", description = "<Nezzliok speaks.>\n\nYou have appeased myself and my chief, so I will tell you that which you seek to discover...\n\nYoung Yenniku is lost to his clan.\n\nHe was taken by the witchdoctor Zanzil the Outcast.  Now Zanzil controls him, body and soul, and only the most potent magic could set him free.\n\nA magic that you do not have, {class}.\n\nPerhaps your Darkspear allies at Bambala in the east can offer a hope of Yenniku's salvation.  But that, I doubt.", completion = "Zanzil the Outcast??\n\nIf Yenniku is held by that troll, a vile and powerful witchdoctor, then I fear that only a faint hope remains.  Faint.  And tiny as the smallest insect.\n\nFortunately, I have some suspicions of my own.  Suspicions which may lead to Yenniku's salvation.", objectives = "Speak with Kin'weelay at Bambala.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26303] = { id = 26303, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mind's Eye", description = "The Mind's Eye is held by an ogre mage, in the Mosh'Ogg ogre mound just to the south.  His name is Mai'Zoth.  I know him from when the Darkspears dwelt in Stranglethorn - he is vicious, and his magic is strong.\n\nAnd if he has the Mind's Eye, then his magic will be stronger still.\n\nYou must face Mai'Zoth and wrest from him the Mind's Eye.  It is a perilous task, but it is the only hope we have of saving Yenniku.", progress = "Greetings, {name}.  The spirits sing praise of your bravery, yet they tell me no tales of your quest against Mai'Zoth.\n\nDo you have the Eye?", completion = "You retrieved the eye!  Your might is the stuff of legends, {name}!\n\nAnd in getting the Eye, you must have defeated Mai'Zoth and sent him to the Nether.  That is why the spirits would not mention him before.\n\nIt is good that he is gone from the world of flesh and bone, but now that he is in the realm of spirits...I fear he will begin a new reign.\n\nBut that is a worry for another time.", objectives = "Obtain the Mind's Eye from Mai'Zoth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26304] = { id = 26304, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nighttime in the Jungle", description = "One year ago, my mother - that is, the troll who took care of me - was taken by the Skullsplitters of Zul'Mamwe.  Young and headstrong, I ran in after her, only to see her being pushed toward a burning brazier by a dozen of their warriors.  I hid behind a tree and watched as they grabbed her and... and...\n\n<Kil'karil looks away.>\n\nAt nighttime, the lights from their braziers reflect off the treetops and keep me awake.  Please, {name}... travel south into Zul'Mamwe and put them out.", progress = "Please, {name}... put out the awful fires.", completion = "My mother's spirit rests well tonight, {name}.\n\nAs will I.", objectives = "Put out 8 Zul'Mamwe Braziers at Zul'Mamwe in Northern Stranglethorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26305] = { id = 26305, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saving Yenniku", description = "I have reshaped the Mind's Eye into a Soul Gem.  Its purpose is twofold: you must use it to stun Yenniku, and once stunned place it upon his head to entrap his soul.\n\nMy suspicions that I spoke of earlier were correct: the spirits tell me that Yenniku dwells not with Zanzil the Outcast, but within the Ruins of Zul'Mamwe, to the southwest.  Once you have freed Yenniku's spirit, return to Nimboya at Grom'gol.", progress = "{name}.  Kin'weelay told me you set out to capture Yenniku.\n\nIs it true?  Do you have him?", completion = "You've done it!  You freed Yenniku from the will of Zanzil and the tyranny of the Skullsplitter, and completed the mission I had thought was so hopeless.  Zanzil still looms a threat in the Cape of Stranglethorn, but for now, I at least know that the soul of my chief's son is free.\n\nOur tribe will remember your name in songs, {name}, and we will etch your tale in stone so that it will live forever.", objectives = "Bring the Filled Soul Gem to Nimboya.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26306] = { id = 26306, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Start Taking Back", description = "Today we make the first strike at the heart of the savage Vilebranch tribe. Show no mercy, {name}; this is no longer just a spat between trolls. Every victory of the Revantusk is a victory for the Horde!\n\nThe Vilebranch headhunters and witch doctors will be the first to go. Make your strike against the lower terraces and report back to me with blood on your weapons.", completion = "Well done, {name}! Let the Vilebranch flee in terror from the sight of you!", objectives = "Kill 5 Vilebranch Witch Doctors and 5 Vilebranch Headhunters in Jintha'Alor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26307] = { id = 26307, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death to the Vilebranch", description = "We won't give them a chance to react. You must re-enter Jintha'Alor and charge all the way to the upper tiers.\n\nThe Vilebranch berserkers and shadowcasters are dangerous enemies, {name}. When the others see their bodies thrown across the walls, they'll know we mean business.\n\nDon't leave any Vilebranch hearts beating!", completion = "It won't be long until we're the only trolls left breathing on these walls.", objectives = "Kill 5 Vilebranch Berserkers and 5 Vilebranch Shadowcasters in Jintha'Alor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26308] = { id = 26308, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Ours Now", description = "Only the strongest and foulest Vilebranch are left now. The soul eaters and blood drinkers, foul worshippers of the evil god Hakkar.\n\nThey are FOOLS! They cling to old, defeated beliefs. I won't tolerate their crimes against the Revantusk any longer.\n\nStrike the final blow. Claim Jintha'Alor for the Revantusk... claim it for the Horde!", completion = "There are none left to oppose the Revantusk! Any stragglers will be quickly taken care of.\n\nYou've done my people a great honor, {name}.", objectives = "Kill 5 Vilebranch Blood Drinkers and 5 Vilebranch Soul Eaters in Jintha'Alor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26309] = { id = 26309, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Vessels", description = "The Vilebranch trolls here used to drink the corrupted blood of the god Hakkar himself for power. They boiled it in crude pots before drinking, dark vessels full of unholy strength.\n\nHakkar was killed long ago, of course. But the interesting thing... I still see some cauldrons bubbling up there. Bring me back a few and we'll see just what they've got cooking.", progress = "Be careful near those cauldrons, {class}. The Vilebranch won't let you take their treats without a fight.", completion = "First the spiders and now this. I can smell the venom in this blood... it's the same as the skitterlings, but stronger.\n\nThe Vilebranch and spiders... there's some potential here.", objectives = "Collect 5 Vessels of Tainted Blood from Jintha'alor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26310] = { id = 26310, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All That Skitters", description = "A moment if you're going up there, {class}...\n\nI've got a few brokers quite interested in potent toxins. I couldn't help but notice the spiders scurrying around near here... not giant ones, about the size of your hand.\n\nThe skitterlings are a hue I've never seen before in this area. Could you collect a few for me and bring them back?", progress = "How many did you get?", completion = "Oh yes... I was wise to ask you to get these. How fascinating.\n\nCome here, my pretties. Into the bag you go.", objectives = "Collect 8 Skittering Spiderlings in Jintha'Alor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26311] = { id = 26311, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unfamiliar Waters", description = "The Warchief has designs to launch an all-out assault on the Twilight Highlands. Once there we hope to ally with the Dragonmaw orcs.\n\nThrough my own sources I've discovered that a Dragonmaw orc resides here, in Orgrimmar. He is known as Herezegor Flametusk, and once he commanded legions of their warriors.\n\nHis insider knowledge is precious to us. Find Flametusk and obtain for us a chart of the Twilight Highlands waterways.\n\nLast I hear, Flametusk was washed up at a bar in the Valley of Honor...", progress = "<Sauranok is surprised to see you back so soon.>\n\nAh, {class}, you return. What have you discovered?", completion = "<Sauranok seems uninterested in the map as you relate your story.>\n\nTwilight Assassins followed you to the bar? Here, in Orgrimmar?\n\nThe Warchief won't be happy about this.\n\nContinue your preparations for the invasion and I will investigate.", objectives = "Locate Herezegor Flametusk at the Wyvern's Tail inn within the Valley of Honor in Orgrimmar, and obtain a Twilight Highlands Coastal Chart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26312] = { id = 26312, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crumbling Defenses", description = "When da attack started, we pushed out to take da field as quickly as we could. Dere forces were deep and endless... we underestimated dem. Now some of our best shaman be stranded out dere, exhausted, far from our defenses.\n\nMake your way out and take da pressure off of our stranded brothas. Even a small break in battle be a chance to get much needed room ta breathe.\n\nBe swift, {class}.", completion = "Thank you, {class}. Many Earthen Ring owe dere lives to ya dis day.", objectives = "Relieve Tawn Winterbluff, Stormcaller Mylra, and Hargoth Dimblaze by helping them to defeat their opponents.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26313] = { id = 26313, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Core of Our Troubles", description = "Elementals are chaotic by nature, but dis kind of organized aggression is out of character. More so down here where dere deaths be a bit more permanent. I suspect dis is Therazane the Stonemother's doin', but I have to be sure.\n\nDestroy da Irestone Rumblers and bring me their cores. We'll be settlin' here and now if dis is da Stonemother's hatred brought down on us.", progress = "We've never been claimin' a great friendship with da  Elemental Lords, but we still be trustin' in a bit of security in da chaos. As long as dey be remainin' unorganized, we've been havin' little to fear.\n\nIf the Stonemother is truly rallyin' da earth against us, we be havin' a great deal more to be fearin'.", completion = "Dese are in surprisingly good condition - good work, mon.", objectives = "Collect 6 Irestone Cores.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26314] = { id = 26314, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On Even Ground", description = "We're fortunate dat those giants be havin' such bad aim. Luck is sure to be favorin' dem eventually though.\n\nWe need to get dem off da battlefield, but I don't tink takin' dem head on would be very smart.\n\nTake dis grapplin' line, get a good hold on one of their ankles and pull their legs out from under dem. Once dey are on da ground, dey should be easy ta be finishin' off.", completion = "Dat will slow their assault a bit while Norsala be findin' a way to calm'm. We've no desire ta be remainin' enemies of Therazane the Stonemother.", objectives = "Use the Elementium Grapple Line to pull 3 Servants of Therazane off of their feet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26315] = { id = 26315, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imposing Confrontation", description = "Have ya seen the looming giant in the distance to the northeast? Dat is Boden the Imposing, one of Therazane the Stonemother's Stone Lords.\n\nWe be knowin' little of da Stone Lords, but Boden is not known ta be very level-headed. Sadly, he seems to be da one leadin' dis assault, so he's the one we must be confrontin'.\n\nTake dis proclamation to him and read it aloud on behalf of da Earthen Ring. I know it be a bit of a stretch to think words will settle dis, but we have to try. Be cautious.", progress = "Did ya confront Boden yet?", completion = "Yeah, mon... dat's about the reaction we were expectin'.\n\nHe mentioned Diamant though? If da two don't get along, perhaps this Diamant be a bit less brash den Boden. At least it's somethin'.\n\nLet me see if I can get da earth to tell me where we might be findin' dis Diamant.", objectives = "Read the Earthen Ring Proclamation to Boden the Imposing.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26316] = { id = 26316, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What's Keeping Kharmarn?", description = "The cataclysm tore open deep caves beneath Frostmane Hold and troggs flooded out of their warrens. They succeeded in displacing the trolls who used to live there and they stand to drive us out if we do not act.\n\nHigh Tinker Mekkatorque hired the renowned demolitionist, Kharmarn Palegrip, to close the caves and stem the trogg advance. We've received no word about whether he was able to stop the troggs. Would you look for him at his camp near Frostmane Hold, to the south beyond the Toxic Airfield?", completion = "It won't be tough to collapse th' tunnel, but I'm goin' to need my team an' my equipment 'afore I can get to th' task.", objectives = "Find Kharmarn Palegrip at his camp in Frostmane Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26317] = { id = 26317, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lashtail Hatchling", description = "Upon dealing the final blow to the lashtail eggs, you look down to see a newborn hatchling looking back up at you.  You can see it studying you, learning your features and following your movements.\n\nThe lashtail hatchling has formed a bond with you.\n\nYour original assignment was to thin out the raptors, but you have fulfilled your egg quota, and this one is an innocent newborn.  Perhaps someone back at Grom'gol Base Camp will know what to do with a raptor hatchling.", completion = "Yes, the little one seems to have taken a liking to you.  I suppose that one raptor alone and raised among orcs is much less deadly than a whole pack of them.  Keep her, {name}... she may come in handy.\n\nIn fact...", objectives = "Bring the Lashtail Hatchling to Far Seer Mok'thardin at Grom'gol Base Camp.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26318] = { id = 26318, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finishin' the Job", description = "My team has finished settin' up th' powder kegs and th' detonator at the bottom o' th' cave in th' western part of Frostmane Hold. All you need to do is venture down there and activate th' detonator to explode the powder and collapse those tunnels.\n\nThat'll stop th' flow of troggs from th' deep parts of th' earth. Mekkatorque'll have an easier time of dealin' with the remainin' troggs if you can take out their leader, who calls 'imself Boss Bruggor. Good luck, {name}.", progress = "Well, is th' job done?", completion = "I could feel th' explosion way up here! My boys did a fine job riggin' up that blast, but it wouldn't have happened without your help. It's only fair that I split my contract payment with you for helpin' me finish th' job.", objectives = "At the bottom of the cave in Frostmane Hold, kill Boss Bruggor and activate the Detonator to detonate the trogg tunnels.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26319] = { id = 26319, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets Revealed", description = "There is a shaman here, Thoralius, who might be able to aid us. He is a friend of Gryan's who has recently come to Westfall to study the elemental devastation that has befallen us.\n\nSpeak to Thoralius and see if there is something that he can do to shed some light on the identity of this shadowy figure.", completion = "Hmm, yes, perhaps I could be of some assistance. When I was in Northrend I helped the people of Valgarde uncover some of the mysteries of the vrykul by delving into the spirit world. Perhaps the same could be done here.", objectives = "Speak with Thoralius the Wise at Moonbrook in Westfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26320] = { id = 26320, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Vision of the Past", description = "This incense will put your body and mind in a deep meditative state. Once the trance begins you will be pulled into the spirit world. Do not fight the trance once it has begun, {name}. Allow the spirits to show you what they know.\n\nYou must leave now. Go to the Deadmines, a place which I am told holds great significance in the history of Westfall. Once inside, use the incense.\n\nYou may enter the Deadmines through the old farmhouse south of here. Follow the homeless. \n\nReturn to Gryan with your discovery.", completion = "WHAT? VanCleef had a daughter?", objectives = "Enter the Defias Hideout and follow the trail of homeless to the Deadmines dungeon. Enter the Deadmines dungeon and use the Incense Burner to see into the past.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26321] = { id = 26321, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Think She's Hungry", description = "It looks like your young raptor is hungry.  If you're looking to keep her, why don't you find something for her to eat?  The lashtail often attack the camp of the Murkgill murlocs, just to our north.\n\nShe probably isn't strong enough to hunt on her own yet, but I'm sure she will eat freshly killed murloc meat.", completion = "She looks bigger already!  You can see, these raptors grow quickly.  You are lucky to have found such a strong companion.\n\nKeep her by your side as long as you can, {name}.  I'm sure she will prove to be an asset in the future.", objectives = "Kill Murkgill murlocs in Northern Stranglethorn, and let your Lashtail Raptor eat 40 bites of their meat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26322] = { id = 26322, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rise of the Brotherhood", description = "I had no idea that VanCleef had a daughter, {name}. If there was one thing that man was exceptionally skilled at, it was keeping secrets.\n\nHow tragic. Poor thing witnessed a horrible act. Had I only known.\n\nWhat was that? Did you hear something? It seems as if the gnolls are pulling back... where are my guards?\n\nON GUARD, {name}!", completion = "I will deploy a battalion of soldiers to Westfall at once! With the Defias Brotherhood reborn, an old threat to the kingdom is renewed.", objectives = "Bear witness to the rise of the Brotherhood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26323] = { id = 26323, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Favored Skull", description = "Your pet raptor seems to have found a new toy: a skull, from a nearby troll skull pile.\n\nWhat sets this skull apart from the rest is beyond you, but for some reason, she won't put it down.\n\nNimboya at Grom'gol Base Camp seems to be somewhat of a skull expert, judging by the skull piles he keeps.  Maybe he'll have some idea what makes this one so special.", completion = "What do we have here?  A young raptor, and her pet {race}.  Hah!\n\nMore importantly, what is that skull you have there?  This was no ordinary troll.  He was big...\n\n\n\n... and strong, too.  Let's see what we can do with this one.\n\nDon't go anywhere.", objectives = "Return to Nimboya at Grom'gol Base Camp and show him your Lashtail Hatchling's new skull.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26324] = { id = 26324, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where Is My Warfleet?", description = "The Highlands are the home of the Dragonmaw orcs. If we show them our might they would ally with us against the Twilight's Hammer. I am certain!\n\nThe fleet is gathering at Bilgewater Port in Azshara but there are reports of delays.\nYou did good getting the goblins to work, I need your skills here too.\nFind Warlord Krogg in Azshara and see what is taking so long.", completion = "What, another message from Hellscream? His patience is thinner than calf's hide.\n\nHave you ever worked with goblins before? Everywhere is another hidden cost! Our ships lie half-assembled and the air fleet is scattered to the winds.\n\nIf this invasion is going to happen, I'm going to need your help.", objectives = "Speak with Warlord Krogg at Bilgewater Port in Azshara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26325] = { id = 26325, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Nose for This Sort of Thing", description = "<The skull speaks to you.>\n\nI live?  No, I do not... but I can.\n\nThat raptor you have is wise to have found my skull among what must have been so many.  In life, I was strong, powerful, a lord among trolls.  With your help, I can be a lord once more.\n\nThe Bloodscalps at Zuuldaia hoard magical fetishes that can help me return.  They hide these artifacts under the sand.  Use your hatchling to find these artifacts, {name}... then throw them in the pot.", progress = "<The large troll skull bubbles to the surface.>\n\nHow many did you find?", completion = "<You drop the fetishes into the pot.>\n\nYes... yesss...\n\nMy spirit is strong again, {race}, and I am ready to return to the world.  Now I need a body.", objectives = "Use your Lashtail Hatchling to sniff out 8 Zuuldaian Fetishes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26326] = { id = 26326, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Very Earth Beneath Our Feet", description = "Only one piece of the World Pillar remains, and it is in the hands of the Stonemother herself. Worse, the temple has come under siege by elementals and giants. It's not a terrible leap of logic to assume they're acting by her will.\n\nGo out and meet the elementals in battle to the northwest. Work with Torunscar and Norsala to find a way to communicate with their leaders and seek out the World Pillar. We would prefer such be done peacefully, but we will do whatever we must to seal the rift.", completion = "Hey, mon! Thank ya for comin'.\n\nWe weren't ready for dis kind of attack. We been expectin' da Twilight Cult, but not elementals... we've got no idea what upset dem so much that dey would turn on us like dis.\n\nYou haven't been out dere killin' them, have you?", objectives = "Find Earthcaller Torunscar just northwest of the Temple of Earth, in the Jagged Wastes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26327] = { id = 26327, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anvilmar the Hero", description = "You don't want to waste your time talking to me right now, <lad/lass>. Thargas Anvilmar himself is just on the other side of these wagons.\n\nSurely you've heard of him? He fought to defend the Thandol Span from the Dark Iron alongside the King of Stormwind! He's one of the finest heroes of Ironforge.\n\nRight now though, he's in the thick of it! Go out there and let him know you're ready to help. Just keep a good distance, he swings wide.", completion = "Well met! If you've got a weapon on you, I'll take any help I can get clearing out these crazed fools!", objectives = "Talk to Thargas Anvilmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26328] = { id = 26328, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rocky Relations", description = "<Norsala reaches to the ground in an attempt to discern Diamant's location, but jumps back in shock after a moment's contact.>\n\nMy! Dat was unexpected. Diamant ain't far at all. When I reached out ta him, he spoke back wit me and told me where we could be finin' him. Head towards tha northeastern edge of the Jagged Wastes - Diamant will be expectin' ya.\n\n{name}, be careful. It may be unlike an earth bein' to lay an ambush, but it was unlike dem to siege the temple in da first place.", completion = "Ah... you must be the {race} that I was expecting.\n\nYou have come on behalf of the Earthen Ring then?", objectives = "Find Diamant the Patient at the northeast edge of the Jagged Wastes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26329] = { id = 26329, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One More Thing", description = "Well, it's time to start packin' up and movin' on to the next job. There's always somethin' else to blow up out there. Somewhere, there's a mountain needs movin' or a gorge that needs carvin', and I'll be there to do it.\n\nI don't suppose you'd do me one more favor? Would you take this report back to High Tinker Mekkatorque in New Tinkertown? He needs to know that th' troggs won't be botherin' his people again anytime soon.", progress = "Welcome back, {name}.", completion = "<The high tinker reads Jessup's report.>\n\nSplendid news! With the troggs taken care of, we should be able to turn our attention to Crushcog's troublemaking.", objectives = "Bring Kharmarn's Report to High Tinker Mekkatorque in New Tinkertown.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26330] = { id = 26330, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Who's a Big Troll?", description = "<The skull speaks once more.>\n\nMy soul is ready, but my body is not.  The Bloodscalps desecrated my old body long ago.  The horrors that they inflicted upon me... my spirit watched on while they tore my body apart and, and... I can't go on.\n\nTheir chief, Gan'zulah, presided over the gruesome acts.  In fact, if memory serves, he was a strong, powerful troll... about the same size as I was.  What a fine coincidence.\n\nYou know what to do, {race}.  Make it quick.", progress = "<You hear the skull's voice:>\n\nGan'zulah...", completion = "You have done well, {race}.  Only one more step remains before I may return.", objectives = "Obtain Gan'zulah's Body from Zul'Kunda.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26331] = { id = 26331, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushcog's Minions", description = "Our old enemy, Thermaplugg, is doing his best to keep us from rebuilding and finishing our reclamation of Gnomeregan. He's sent one of his most loyal henchmen, Razlo Crushcog, and a force of irradiated gnomes to harry us.\n\nThey've taken over an old arsenal up the road to the north, and Crushcog's technicians are repairing those weapons. We have to stop them before they're able to get those mechano-tanks back online. Go to Crushcog's Arsenal and eliminate as many of the technicians as you can.", completion = "That should set back Crushcog's plans a bit, but we can't rest until he is defeated and Chill Breeze Valley is secure.", objectives = "Kill 8 of Crushcog's Minions at Crushcog's Arsenal. You may kill Irradiated Technicians or Crushcog's Battle Suits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26332] = { id = 26332, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skullsplitter Mojo", description = "<The skull speaks again.>\n\nI have my body, thanks to you, your raptor, and Gan'zulah.  Now, if I remember correctly, you and your witch doctor friend will need some mojo to complete this ritual.\n\nThe Bloodscalps keep mojo in Zul'Kunda, but it is weak.  Your Darkspears' mojo will not work either.  No... you want to take from the Skullsplitter trolls, across the river to the east.\n\nHurry back, {race}.  I will be watching...", progress = "<The large troll skull floats around within the cauldron.>", completion = "<You throw the mojo into the pot.>\n\nExcellent work, {race}.  You and your raptor have done a great thing.  Hakkar would be most pleased...", objectives = "Obtain 6 Skullsplitter Mojos from Skullsplitter trolls in the Ziata'jai Ruins and the Balia'mah Ruins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26333] = { id = 26333, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Tanks!", description = "We've lost more than a couple scouts trying to find out what exactly Razlo Crushcog plans to do with all those mechano-tanks his irradiated technicians are repairing.\n\nWe can't afford to take it slowly anymore. We must act before Crushcog turns his followers and his weapons on us.\n\nThis techno-grenade packs enough explosive power to destroy the mechano-tanks and deny Crushcog their use. Take it north with you along the road to Crushcog's Arsenal and take out those tanks!", progress = "Have you managed to take out any of those mechano-tanks Crushcog's men are working on?", completion = "Mekkatorque will be pleased to hear that you've ruined Crushcog's plans to use our old weapons for his followers. Without the mechano-tanks under his command, he'll be weak and vulnerable.", objectives = "Use the Techno-Grenade to destroy 5 Repaired Mechano-Tanks at Crushcog's Arsenal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26334] = { id = 26334, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloodlord Mandokir", description = "{race}.  {race}, {race}, {race}... you didn't think I was a friend, did you, {race}?  Ah, ha ha haaaa!\n\nYou've served your purpose.  I've returned to the realm of the living, and it's all thanks to you.  So, instead of killing you, I'm going to make you a deal instead.\n\nGive me the raptor.\n\nYou must already know that she's no normal raptor, and I need a replacement for Ohgan.  Do it, or both you and the witch doctor will taste my rage.", progress = "All I ask is the raptor, {race}.  Give it to me, and the troll lives.", completion = "I'm glad to see you've come to your senses.\n\nCome and visit us in Zul'Gurub sometime, {race}.  I'll be watching...", objectives = "Deliver the Lashtail Raptor Egg Fragment to Bloodlord Mandokir in Grom'gol Base Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26335] = { id = 26335, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ready the Navy", description = "Hellscream expects an armada of ships for his invasion, but the docks here are weeks behind schedule. Costs are rampant and quality is poor. Corruption is the problem, {name}! And I need you to root it out.\n\nThe Foebreaker, a warship berthed at the northwest pier, should have been outfitted days ago. Something reeks. Go there and oversee the construction yourself.\n\nFind out who's disrupting our naval preparations and deal with them!", completion = "<Here, in excruciating detail, are the blueprints for the Foebreaker.>\n\n<You twist the documents every which way, trying to make sense of the incomprehensible scribbles, notes, and corrections.>", objectives = "Investigate the Hull of the Foebreaker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26336] = { id = 26336, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shakes O'Breen", description = "You're all right, {name}. It's not every day you come across a so-called hero that has a clue what they're doing once they get this far from home, so I'll let you in on some more work.\n\nI've a friend by the name of Shakes O'Breen. He's the captain of a crew of pirates, the Blackwater Raiders; good men, respectable as pirates go. They dock at Faldir's Cove, hidden along the southern shore.\n\nI'm sure O'Breen will have lucrative jobs for you if you're interested.", completion = "Ahoy, {class}. Any friend of Skuerto is a friend of mine.\n\nYou'll find plenty of work needs doin' around here. We're not sittin' in this cove twiddlin' our thumbs by choice.", objectives = "Find Shakes O'Breen at Faldir's Cove in Arathi Highlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26337] = { id = 26337, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beating the Market", description = "<It's not hard to see why the Foebreaker is behind schedule. Every other day, a foreman comes in and changes the blueprints.>\n\n<Most troubling are the recent alterations. The workers have been ordered to remove rivets to save on costs!>\n\n<You'd better track down one of the Bilgewater foremen responsible for this and make an example out of him, before any Horde lives are lost in a faulty ship.>", completion = "So they were trying to skimp on production costs? Unacceptable!\n\nI'm glad you knocked some sense into them. If that foreman makes good on his word, our fleet will be ship-shape in time for the invasion.", objectives = "Track down a Bilgewater Foreman somewhere in Bilgewater Harbor and knock him around a little.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26338] = { id = 26338, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Population Con-Troll", description = "I understand you may be headed to Zul'Kunda soon.  While you are there, I have a small task for you.\n\nThe trolls are outgrowing Stranglethorn.  The Bloodscalp in the West, the Skullsplitters in the East... they pour out of their ruins and into the jungle, disrupting the natural balance of the region.  It is time we restored that balance.\n\nZul'Kunda is the Bloodscalp capital.  Inside you will find the most high-ranking Bloodscalps.  Reduce their numbers, then return to me.", completion = "Balance is restored - for now.  We may call on you again in the future, {name}.", objectives = "Slay 7 Bloodscalp Mystics, 7 Bloodscalp Hunters, 7 Bloodscalp Scouts, and 1 Bloodscalp Beastmaster.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26339] = { id = 26339, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Staging in Brewnall", description = "While High Tinker Mekkatorque, his military advisors, and I finalize the plans for the attack on Razlo Crushcog, I've sent my assistant ahead to Brewnall Village to begin preparations.\n\nTo get to Brewnall Village, follow the road southeast out of town. Once you arrive, find Jarvi Shadowstep and see if he needs any help. Our dwarven cousins have dispatched a cadre of mountaineers from Ironforge to join us in the fight against Crushcog.", completion = "Ah, yes, Kelsey told me to expect you. There's still much to do before we can take on Crushcog.", objectives = "Speak with Jarvi Shadowstep at Brewnall Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26340] = { id = 26340, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hunt", description = "Of all the places to end up across Azeroth, I'm stuck here in Grom'gol.  With the marauding wildlife, the caravan raids, and the constant threat of troll attacks, I'm surprised I've survived for this long.\n\nCould be worse, I suppose.  At least here in Grom'gol we have walls and guards.  There's a group of hunters up north that set up camp right in the middle of the jungle!\n\nI see people heading there all the time.  If you're looking for trouble, feel free to head up there.  I'll stick with my Grom'gol.", completion = "Hmm?  Barnil's the name.  And you are...?", objectives = "Report to Barnil Stonepot at Nesingwary's Expedition in Northern Stranglethorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26341] = { id = 26341, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Stone Shards", description = "I've scouted all over these highlands, {name}, and there's one thing I've found I haven't been able to explain.\n\nTo the northeast of here, there's a circle of stones, like the others you'll find everywhere in Arathi... but the largest and most imposing of them, built into the mountainside itself.\n\nJust between you and me, I heard voices while I was there. Whispers of the earth. If you're the curious type, you could go see for yourself...", completion = "<The shards pulse softly, and a whisper slowly echoes through your head.>\n\nHelp...", objectives = "Investigate the Shards of Myzrael.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26342] = { id = 26342, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paint it Black", description = "We have reliable intelligence that Razlo Crushcog has taken up a defensive position on the island in the middle of frozen Iceflow Lake. To make matters worse, he's surrounded himself with a network of sentry-bots that will detect any possible attackers.\n\nIf we're to take on Crushcog, we'll need to take out those sentries. This device launches a dark, sticky paint that will coat the optical sensors of Crushcog's sentry-bots. Use it to take out his early warning system.", progress = "Were you able to blind Crushcog's sentries?", completion = "You've given us just the opening we'll need to get the drop on Crushcog. Excellent work, {name}.", objectives = "Use the Paintinator to blind 5 of Crushcog's Sentry-Bots.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26343] = { id = 26343, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supply and Demand", description = "\"The finest leathercrafter of the South Seas and the worlds old and new.\" That's what they call me. Me! Drizzlik! The finest lea... Ahem. Well.\n\nMy leather goods are known far and wide as the most exquisite, a connoisseur's choice!\n\nI've just received an order from Director Riddlevox of the Tinkers' Union for a dozen of his favorite Excelsior-line boots. Our best sellers, actually.\n\nTo start on the basic shape, I'll need crocolisk skins from the crocs along the river in Northern Stranglethorn.", progress = "My equipment is all ready to go, {name}, I just need those skins. We don't want to keep Riddlevox waiting, that's for sure.\n\nIt's not a good idea for anyone to keep the chief inventor of the Tinkers' Union unsatisfied.", completion = "These skins should do. Their quality isn't too important, given that they'll make up the inside layer of the boots, but it's still important that they're comfortable.\n\nIf they're a bit too rigid, I'll use some tiger blood to soften it up. Tricks o' the trade, you know?", objectives = "Bring 2 Large River Crocolisk Skins to Drizzlik at Nesingwary's Expedition.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26344] = { id = 26344, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Some Assembly Required", description = "Well, I've got the basic shape of the boots worked out, and they're coming along fine, but the skins you brought aren't going to be quite enough for the inner layers.\n\n\"What are we going to do, Drizzlik?\" No doubt the question on your lips, and well, isn't it lucky you're talking to Drizzlik, because he's going to tell you what we're going to do!\n\nThe inner layers will never really be seen, so we'll just get some of the thicker, cheaper skins from the crocs around Lake Nazferiti to fill the boots out.", progress = "Drizzlik's Excelsior leather boots, finest workmanship, one-hundred percent high quality saltwater crocolisk skin boots. None finer!\n\nCan't beat a glowing description like that, can you?\n\nExcept, maybe, if you have those skins for me?", completion = "My boots... they're like sausages, {name}. Look great, taste great. I tell you they're filled with nothing but the finest ingredients and meats, and you eat it, and you love it.\n\nIt's safer--and more enjoyable--if you just trust me, and don't ask too carefully what's really inside.", objectives = "Bring 5 Snapjaw Crocolisks Skins to Drizzlik at Nesingwary's Expedition.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26345] = { id = 26345, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Excelsior", description = "With the inside finished, all that's left is to add the outer layer. For this, I use only the best elder croc skins. They are more durable and a better canvas--if you will--for adding the designs and accents that make Drizzlik's Excelsior line.\n\nIt's hard to find that perfect skin though, the only one that fits my plan is the skin of an elder snapjaw crocolisk.  Find them to the south, near the border with the cape.", progress = "I read somewhere that the elder crocolisks are slowly dying out... bad news for my business, isn't it?\n\nAnyways, I hope you have that elder snapjaw crocolisk skin for me!", completion = "Great! Thanks to your help I'll have this order filled and sent off to Director Riddlevox on the next boat to Undermine. Ahead of schedule, even!\n\nFor all your hard work, here, I made some extras, so take a pair. It's on Drizzlik.\n\nAnd remember, there's no boot so fine as one of Drizzlik's Excelsior line!", objectives = "Bring an Elder Crocolisk Skin to Drizzlik at Nesingwary's Expedition.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26346] = { id = 26346, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Myzrael's Tale", description = "As the stone goes quiet, you're left with a vague sense of unease. Something isn't right.\n\nPerhaps you should tell Skuerto of what you've done so far.", completion = "Say no more, {name}. I followed up with an... \"old friend\" while you were gone. I should've known better than to send you to those shards.\n\nWe've both made a grave mistake in involving ourselves in this. Luckily, I \"persuaded\" my boy Gerrig to tell me what to do if this happened.", objectives = "Return to Skuerto at Refuge Pointe in Arathi Highlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26347] = { id = 26347, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keeper of the Flame", description = "The night the Lighthouse Keeper's family died was horrible.  I watched, helpless, as Old Murk-Eye led the attack.  But what's done is done and now my concern is for the lives of the sailors on The Great Sea whose ships come close to the perilous rocks of the coastline.  With no one to keep watch on the flame the responsibility has fallen upon me.\n\nHelp me keep the torch lit by bringing me chasm ooze from the slimes in the Raging Chasm to the northeast.", progress = "The flame will not burn for long without ooze, {name}. We used to use oil back in the day, but it was hard to come by!", completion = "Praise you, brave {class}.  The rocks of the Westfall Coast shall be lit thanks to your hard work.  Many lives will be spared so long as the torch is kept lit.\n\nI died needlessly on this very shore.  My afterlife plight is to see that no others follow my destiny.", objectives = "Bring 5 Chasm Oozes to Captain Grayson at the Westfall Lighthouse.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26348] = { id = 26348, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Coast Isn't Clear", description = "You probably noticed all of the shipwrecks along the coast.  The Great Sea is treacherous indeed.  The coast of Westfall needs to be kept clear, so that if sailors find their way to our beaches, they are safe.  The Murlocs are trouble though.\n\nKill murloc tidehunters and oracles and I will see to it that you are rewarded.", completion = "Well done, {name}.  You have quite a knack for combat.  Thanks to you the Coast of Westfall is a safer place.", objectives = "Kill 7 Murloc Tidehunters and 7 Murloc Oracles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26349] = { id = 26349, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Coastal Menace", description = "When my life was ended upon the rocks, I had no clue what the afterlife held for me.  The Lighthouse was black that night because Old Murk-Eye had scared the keeper's family off.  They returned and re-lit the flame but Old Murk-Eye coerced the weaker minded murlocs to raid the Lighthouse with him once again.  The second time the family was not so lucky and before my eyes they perished helplessly.\n\nSlay Old Murk-Eye if you see him along the shore and bring me one of his scales and I shall reward you.", progress = "Have you laid waste to the menace known as Old Murk-Eye yet?  He has been spotted roaming the coastline of Westfall.\n\nReturn to me when the foul beast is dead.", completion = "So the foul heathen, Murk-Eye is dead.  Well done, {name}.  By your hands one life was laid to rest but perhaps many more were saved.  The Great Sea, wrought with danger as it is, shall be a wee bit safer this night thanks to your heroics.", objectives = "Bring a scale of Old Murk-Eye to Captain Grayson at the Westfall Lighthouse.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26350] = { id = 26350, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Priestess Hu'rala", description = "Thank you, {name}.  I know you didn't have to save my life, and... well, I am thankful.\n\nThe return of Bloodlord Mandokir is ill news.  He was killed inside Zul'Gurub several years ago, and we thought we had seen the last of him and his kind.  The trolls of Zul'Gurub were attempting to perform a hideous, horrible ritual.  If Mandokir is alive, then it stands to reason that he is not the only one.\n\nThe trolls at Bambala in the east may know more.  Speak with their priestess.", completion = "Mandokir is alive, yes.\n\nYou are responsible, yes.\n\nYou may be able to stop him still, yes.", objectives = "Speak with Priestess Hu'rala at Bambala in Northern Stranglethorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26351] = { id = 26351, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mind Vision", description = "To know Mandokir, you must see Mandokir.\n\nTo see Mandokir, you must use eyes of raptor.\n\nYou have formed bond with raptor: Ohgan'aka: daughter of Ohgan.\n\nTo strengthen bond, we need feathers.\n\nYou will go west, and you will find the feathers, yes.", progress = "Raptor named Ohgan'aka, still your friend.", completion = "You bring feathers, yes.\n\nYou can follow directions, yes.", objectives = "Obtain 5 Jungle Stalker Feathers from Jungle Stalkers in Northern Stranglethorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26352] = { id = 26352, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cozzle's Plan", description = "I may be of Darkspear birth, but I spent my childhood here, in Stranglethorn Vale.  I've seen everything there is to see here in Stranglethorn, but the most offensive is the devastation that the Venture Company has done to the riverbed.\n\nTo make things worse, Foreman Cozzle and his crew have been increasing their activity, and I suspect they have some new plan.  Succeed where I failed, {name}: Kill Cozzle, obtain his key, and steal the blueprints from his apartment.", progress = "The Venture Company's acts against Stranglethorn cannot be forgiven.", completion = "A fuel regulator?  This seems important.  At least, I hope it is.\n\nWe may not have ended the Venture Company's operations, but we at least slowed them down.  Thank you, {name}.", objectives = "Obtain Cozzle's Key from Foreman Cozzle, then obtain the Fuel Regulator Blueprints.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26353] = { id = 26353, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Captain Sanders' Hidden Treasure", description = "If ye be readin' this, it means that Ol' Captain Sanders is in a watery grave.  So my treasure is yours now, ye jest need to follow the clues. \n\nFirst ye need to find me footlocker.  It's probably half-buried in sand by now, along the Western Coast of Westfall near the shipwreck.  There be lots of shipwrecks but only one rusty anchor on the coast.  Find that anchor and you'll find me locker!  Look in there for the next clue.", completion = "The footlocker slowly creaks open.  Sand and water seem to be its only contents. But wait!  A small crab scurries out with a clue to the treasure in his claws!", objectives = "Find Captain Sanders' footlocker and search it for the next clue.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26354] = { id = 26354, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Captain Sanders' Hidden Treasure", description = "The clue to the treasure reads: Good work, matey!  Now ye need to head due east.  East up the bluffs, east to the road.  Look for the ol' chimney ruins near the side of the road.  There you'll find an old barrel with your next clue.", progress = "This looks like the right barrel.", completion = "Good work, treasure hunter!", objectives = "Find the old barrel near the ruined chimney and search it for your next clue.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26355] = { id = 26355, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Captain Sanders' Hidden Treasure", description = "Searching through the barrel you discover another piece of parchment.  This one reads:  Now from this here barrel, face ye North.  Straight as the crow flies, keep ye walkin' till you see the empty jug next to the lone windmill on the sea bluffs.  If ye poke around that jug, ye just might find what you're lookin' for.", progress = "There's a clue sticking out of the empty jug.", completion = "You're on your way to the jackpot, treasure seeker!", objectives = "Search the empty jug next to the windmill for the next clue.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26356] = { id = 26356, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Captain Sanders' Hidden Treasure", description = "Sure enough, deep within the Old Jug there is another clue to Sanders' treasure.  The ink has run in some places and the paper smells like whiskey but you can make out some of the text:  Now that ye found me ol' whiskey jug, you're almost to the treasure!  Just face West from the bottle and walk down to the shore.  Once ye get to the water, keep going!  Swim straight west till you find the island with me treasure chest!", progress = "The lost treasure of Captain Sanders awaits!", completion = "The hinges on the old chest are rusty but they still work.  You force the chest open and take the booty.\n\nCongratulations!", objectives = "Locate Captain Sanders' chest and open it for your reward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26357] = { id = 26357, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Faces of Evil", description = "The Vilebranch have hung their tiki masks all across the walls of Jintha'Alor. The spirits not gonna be watchin' over them much longer.\n\nTake this torch with ya as ya fight through the Vilebranch, {class}. Set fire to their tiki masks. I'll be watchin' from here as their wards and hexes fade away, an' their heretical dark voodoo goes up in smoke.", completion = "Such a pretty site ta see the enemy's hopes burnin'...", objectives = "Use the Tiki Torch to set fire to 8 Tiki Masks at Jintha'Alor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26358] = { id = 26358, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ready the Air Force", description = "I gave Hellscream my personal guarantee that I'd have his airfleet ready this week, but our flagship - The Spear of Durotar - still doesn't have its primary engines installed.\n\nFleep promised me a dangerously shiny new engine last week. Go to her junkyard behind the bank and find out what the holdup is.\n\nThe airfleet is waiting on us, {name}!", completion = "<Fleep wipes her face, plastering an enormous grease smear across her cheek.>\n\nWhat? The Captain said WHAT?\n\n<She shakes her pipe wrench threateningly.>\n\nIt's HIS fault this big beast of an engine is delayed.", objectives = "Look for Fleep at her junkyard within Bilgewater Harbor in Azshara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26359] = { id = 26359, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "See Raptor", description = "We have the feathers, yes.\n\nWe have the {class}, yes.\n\nSpeak with Priestess when you are ready.", progress = "Your vision not Ohgan'aka's, no.\n\nYou are not ready.", completion = "What did Priestess tell you?\n\nThe raptor is daughter of Ohgan, heir to Mandokir's seat.\n\nHah!", objectives = "Speak with Priestess Hu'rala at Bambala to participate in the Mind Vision ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26360] = { id = 26360, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mind Control", description = "Mind Vision is not enough, no.\n\nMind Control, much more powerful magic, yes.\n\nPowerful magic needs powerful reagents, and troll brain is a powerful reagent.\n\nBraddok in Zul'Mamwe, very smart, yes.\n\nHead south, and check out the big brain on Braddok.", progress = "Extra-big spells need extra-big brains, yes.", completion = "Hold on, next part is tough, yes.\n\nLots of chances to fail, yes.\n\nBut {name} and {name}'aka going to be reunited... yes they will.", objectives = "Obtain Braddok's Big Brain from Braddok in Zul'Mamwe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26361] = { id = 26361, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smoot's Samophlange", description = "It was the Captain who insisted his new engines use an induction samophlange.\n\nThose things hadn't even been invented yet!\n\nI tasked Smoot with creating one based on some stolen Venture Company schematics, and he's finally built a working model.\n\nNow that he's got his samophlange, he's drunk with power. He's running all over town with it like a goblin possessed.\n\nSmack Smoot and snag my samophlange, {name}.", progress = "Smoot's a good engineer.\n\nA samophlange can kill from thirty yards if you misalign the reduction caliphracts.", completion = "Excellent! I should have this here engine samophlanginated within the hour.", objectives = "Find Smoot somewhere in Bilgewater Harbor. Tackle him and get the Induction Samophlange.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26362] = { id = 26362, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Be Raptor", description = "Mind Control, very powerful, yes.\n\nWith luck, you can help Ohgan'aka escape from Zul'Gurub.\n\nThen, Ohgan'aka becomes {name}'aka again!\n\nSpeak to Priestess, yes, and help {name}'aka escape.", progress = "Where is {name}'aka?", completion = "What a shame, yes.\n\nThis is what the spirits wanted, yes.\n\nMaybe when you are stronger, you will go into Zul'Gurub and take back your {name}'aka from Mandokir, yes.\n\nFor now, Priestess give you this.", objectives = "Speak with Priestess Hu'rala, then help the Captured Lashtail Hatchling escape from Zul'Gurub.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26363] = { id = 26363, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Summit of Fate", description = "You've done well cleaving through their warriors, {name}. I'd like you to investigate the summit of Jintha'Alor.\n\nWe were prepared for our fiercest battle there, to storm their dark altar, but it's too quiet. Not a sound. It could be a terrible trap, and someone strong should look into it first instead of all of us rushing in.\n\nAnd if it's not a trap... I'm very interested in finding out what happened up there. Bring me back any clues you can find.", progress = "What did you find?", completion = "Dead? All of them, around the altar? And you found these spider idols on them...\n\nA mass sacrifice. They threw their lives to Shadra.", objectives = "Collect 8 Spider Idols from the Vilebranch at the summit of Jintha'Alor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26364] = { id = 26364, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Down with Crushcog!", description = "Our cousins, the dwarves of Ironforge, have agreed to help us in the battle against Razlo Crushcog. Mountaineer Stonegrind is a veteran who knows Dun Morogh well. He and High Tinker Mekkatorque stand ready on a small snow-covered island in Iceflow Lake to the north. Meet up with them there and let the high tinker know when you are ready to face the traitor Crushcog.\n\nTake this orbital targeting device and use it during the battle. It will help guide the high tinker's special weapons.", progress = "Did you face Crushcog? What happened?", completion = "We're finally free of Razlo Crushcog and his interference! With the defeat of Crushcog and his forces, Thermaplugg can't afford to send any more of his followers to the surface. I can't wait for the day when we defeat him for good!", objectives = "Defeat Razlo Crushcog. Speak to High Tinker Mekkatorque at Iceflow Lake when you are ready to begin the battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26365] = { id = 26365, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Redridge Mountains!", description = "While the situation here is dire, other parts of the region are literally quaking from the great upheaval.\n\nI have here a report from Watch Captain Parker of Redridge Mountains, one of our territories east of Elwynn Forest. He is asking for a hero to come to their aid.\n\nWe are spread so thin here that I don't know how we can afford to send anymore military. Would you check on Parker and see what he needs? You will find Watch Captain Parker atop the tower at Three Corners.", completion = "Heard Westfall was in some deep doody.\n\n<Parker doesn't even turn to face you.>\n\nWell, we got our own set of problems here. See them gnolls out there? Looks like they're actin' up again. I don't like it. Don't like it one bit.", objectives = "Report to Watch Captain Parker at Tower Watch in Redridge Mountains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26366] = { id = 26366, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heads Up", description = "Umboda of the Vilebranch is one of their strongest warriors, and a sick butcher.\n\nHe takes the heads of all he slays as trinkets, rewards...even weapons!  It's his turn to be taken.\n\nFind Umboda \"Three-Heads\", slay him, and bring me HIS head! We'll see how the Vilebranch fight when we throw it back over their walls!", progress = "Let's see it!", completion = "The look of fear and confusion on his face... this is what he deserved! Let's make sure all the Vilebranch wear the same look.", objectives = "Defeat Umboda Three-Heads and collect his head.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26367] = { id = 26367, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ongo'longo's Revenge", description = "Ongo'longo was one of us. What outsiders called a Dire Troll, but he was a Revantusk, and a proud warrior like all of us!\n\nThen the Vilebranch took him. They keep him chained up in a pit at the top of Jintha'Alor, made to dance for their sick amusement.\n\nNo chains can hold Ongo'longo. All you need to do is raise his temper, {name}. Fight him until he's enraged enough to remember his true spirit and break free... and then get out of the way!", completion = "I wish I could have been there to see it, {name}! I'll have to hear the story from Ongo'longo himself when this is over.", objectives = "Fight Ongo'longo until he breaks free.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26368] = { id = 26368, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Venomous Secrets", description = "There's more of this curious venom to be had if Shadra's being summoned.\n\nDon't look so surprised... the Forsaken have studied these lands before, and we've encountered the venom queen at least once. Her toxins have proven quite useful in the past.\n\nThey'll prove useful to the Horde once more, too. Be a dear and fetch me as much poison as you can from the spawn of Shadra that lurk in the cave on the summit... I'm sure you'll be covered in it anyway.", progress = "Have you the venom...?", completion = "Mmm, yes... that old nostalgic smell.\n\nYou've done well for the Forsaken, and the Horde.", objectives = "Collect 6 Shadra-Spawn Venom Samples from the Spawn of Shadra in Jintha'Alor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26369] = { id = 26369, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunt the Keeper", description = "Kotonga has told me of Shadra. She is the venom queen, the loa of spiders, worshipped in darkness. If the Vilebranch are performing rituals, I'm not going to let them finish.\n\nCheck the cave behind the altar at the top of Jintha'Alor. Deep within it, one of Shadra's keepers might still be lurking. Kill her and take whatever she carries back here so we can know what's going on.", progress = "Be sure you search her body. I don't want any traps laid by the Vilebranch to be hidden by their deaths.", completion = "The parts scattered, the keepers separated... I see.\n\nThis is a ritual to summon Shadra. They must not have gotten far. It should be destroyed...", objectives = "Kill Morta'gya the Keeper and obtain the Tablet of Shadra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26370] = { id = 26370, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Sentinel Hill", description = "The Defias Brotherhood are not a force to be taken lightly, {name}. What you witnessed was the birth of a ruthless organization of criminals that will stop at nothing to see Stormwind turned to rubble.\n\nI need you to return to Sentinel Hill and let Gryan know that we are sending him troops. I hope it's not too late.", completion = "Five years of work burned to the ground in five minutes. Damn the Defias!\n\nAnd this is only the beginning, {name}! We have a long, hard road ahead of us.", objectives = "Report to Marshal Gryan Stoutmantle at Sentinel Hill in Westfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26371] = { id = 26371, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Legend of Captain Grayson", description = "Have you heard of Captain Grayson? Some say that he's the figment of a drunken sailor's imagination, but anyone in Westfall will tell you that Grayson is real! He's a ghost that haunts the Westfall Lighthouse far to the west, off the coast of the Longshore.\n\nDo you dare investigate?", completion = "Aye... I used to be flesh and blood, just like you, lad. That is, until that fateful day when the murlocs attacked the lighthouse...", objectives = "Find Captain Grayson at the Westfall Lighthouse in Westfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26372] = { id = 26372, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pre-Flight Checklist", description = "This new engine is extremely fast. And dangerous. I'd use the word \"volatile.\"\n\nThat's the way the Captain likes it.\n\nRun back up the hill and let him know that I'll install this bad boy right now and that he should meet me at the construction site.", completion = "My airship has engines? At last!\n\nNow we can rip the heavens a new one!\n\nOnce the ground and naval forces are ready, we're going to light up the skies over the Twilight Highlands.", objectives = "Talk to Captain Krazz at Bilgewater Harbor in Azshara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26373] = { id = 26373, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On to Kharanos", description = "Some of the mountaineers under Stonegrind's command were telling me about the situation out at Kharanos. When the troggs took over Frostmane Hold, it sounds like the surviving trolls fled westward, deep into the heart of the dwarven homeland.\n\nNow, they threaten the dwarven town of Kharanos. It sounds like they're going to need all the help they can get. You should go to Kharanos and introduce yourself to Captain Tharran. Just follow the road east out of Brewnall and keep going until you see the town.", completion = "If Gnomeregan Covert Operations is recommending you, then you must have made quite an impression. Your help will be most welcome here, as we've a wealth of enemies and few enough mountaineers to face them.", objectives = "Speak with Captain Tharran in Kharanos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26374] = { id = 26374, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ready the Ground Troops", description = "It was a bad idea to muster the troops in this festering goblin metropolis. Every vice that coin can buy is within arm's reach. Our mighty veterans are running rampant, blowing years of Northrend back-pay in a city-wide debacle.\n\nCan you make a sweep through the city and gather up any stragglers that have gone AWOL?\n\nMy axebite warriors are unmatched on the battlefield, but I won't have them disgrace their uniforms while on shore leave.", progress = "Have you found my missing troops?\n\nBe sure to search every filthy back-alley. If there's trouble, they'll find it.", completion = "Thank you, {name}! Most of my soldiers have already reported for duty, some a little worse for the wear.\n\nOne night in Bilgewater makes a hard orc humble.\n\nStill, fresh fighting in the Twilight Highlands should restore discipline.", objectives = "Search Bilgewater Harbor and convince 12 AWOL Grunts to report for duty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26375] = { id = 26375, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loose Stones", description = "The Twilight Cultists are taking my rocklings among them.  They drain them and torture them.  Strip them of the very essence that animates them from the stone.\n\nPlease, {race}, free my rocklings. Neither Diamant nor I have the delicacy to smash their chains without hurting them as well.  But we do have a tool you might use.\n\nUse this. Break their chains and set them free.", progress = "It is unbearable to watch. They know no mercy. They should be offered none.", completion = "You are a generous {race}. You give back to the earth that offers you so much. You have my respect. You shall surely have the respect of the Stone Lords with time.", objectives = "Use the Delicate Chain Smasher to release 6 Quartz Rocklings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26376] = { id = 26376, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hatred Runs Deep", description = "I would apologize for Boden, but stone is stubborn.\n\nIt does not sway from its ways without the wear of time.\n\nThe Stone Lords, Boden and I among them, are charged with retrieving the World Pillar.\n\nIn that, we are at odds.\n\nI would extend my patience upon you, {race}.\n\nProve that you are no ally of the Twilight Cult or Deathwing...\n\nCarry our hatred upon them.\n\nStrike swiftly where we cannot.\n\nSucceed and I will listen.", completion = "I have observed you, {race}\n\nYou do not fear shedding Twilight blood.\n\nIn this, I am willing to extend you some degree of trust.\n\nIt is a start.\n\nAll things in time.", objectives = "Kill Dragul Giantbutcher and 12 Twilight Cultists at Lorthuna's Gate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26377] = { id = 26377, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsolid Ground", description = "The Twilight Cult are mining jade crystals near their camp.\n\nFoolish...\n\nReckless...\n\nGather the mined crystals. Take them to the center of their camp. Shatter them against the ground.\n\nThe reverberations and the powered crystal will bring the tunnelers upon them.\n\nThey will learn respect for the earth...\n\nPiece by piece...\n\nRock by rock...\n\n...with time.", completion = "Time brings respect to all.\n\nThe smallest pebble.\n\nThe largest mountain.\n\nThe most stubborn cultist.", objectives = "Gather 6 Jade Crystal Clusters, combine them, and shatter them within the Lorthuna's Gate encampment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26378] = { id = 26378, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Westfall!", description = "Westfall has fallen to hard times, friend. With the threat of the Defias extinguished, the region has become a haven for the homeless and downtrodden. The crime rate of the area has skyrocketed as people fight for shelter and food. Now I hear tale of murder!\n\nIf you are interested in helping the people of the Alliance, Westfall would be a great place to start. Report to Lieutenant Horatio Laine at the Jansen Stead. You'll find Westfall directly west of Elwynn Forest.", completion = "Murder, rookie. That's what you're looking at on the ground in front of us.", objectives = "Report to Lieutenant Horatio Laine at the Jansen Stead in Westfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26379] = { id = 26379, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Aid of the Refugees", description = "You're come to help, I hope? You have no idea what I'm talking about, do you...\n\nI don't have time to fill you in on all of the details, but we had a town in Darkshore, Auberdine, that took some of the worst of the Cataclysm. We're in the process of rescuing some of the survivors, but I need someone with a bit more experience--someone like you--to check in on a refugee camp that we heard about in the south.\n\nLeave things to us up north. Head straight down there and help the refugees however you can.", sourceObjective = "Sentinel Lendra at Lor'danel wants you to speak to Priestess Alinya at the Refugee Camp.", sourceObjectiveStatus = "unverified-source-field" }
quests[26380] = { id = 26380, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bound for Kharanos", description = "I was supposed to be bringing these casks of ale to the inn in Kharanos. They contain a mysterious new ale produced by an upstart brewery based in Brewnall Village. As I was leaving town, I was attacked by a Frostmane troll raiding party. It's going to take me days to repair the wagon!\n\nI don't suppose you'd be willing to do me a favor, will you? These big kegs aren't going anywhere, but I have some smaller sample casks. Would you bring them to Kharanos for me? Just follow the road to the southeast.", progress = "Welcome, visitor. Have you come to the inn to rest, or do you need a new hearthstone?", completion = "These look promising. I've heard great things about the Short and Stout Brewery, but I haven't had the chance to try their ale until now.\n\nWhile you're here, relax a little. If you need a spare hearthstone or wish to make Kharanos your home, just speak to me and I'll be happy to help.", objectives = "Bring the Sample Casks to Innkeeper Belm at the Thunderbrew Distillery in Kharanos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26381] = { id = 26381, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eye of Shadra", description = "Shadra must be summoned, for certain. To allow an opportunity like this to pass us by would be foolish. While the apothecaries can make fine use of the god's venom, they are relatively inexperienced in ritual magic.\n\nFortunately, I am quite familiar with preparing dark convocations. You will bring the scattered parts of Shadra to me, and I will help you bring her to this plane to be taken out.\n\nThe first part is the eye of Shadra, guarded in Agol'watha to the north.", progress = "If the tablet was a ruse, I will not be pleased. Did you find the eye?", completion = "I'm pleased, {name}. That was quicker than I expected.", objectives = "Recover the Eye of Shadra from Agol'watha.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26382] = { id = 26382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Can't Make An Omelette Without...", description = "Marnal has been pestering me about this Shadra plot for days. I'm almost upset he actually found the tablet; I was ready for him to shut up about it.\n\nDespite his high talk of ritual magic, he's still going to need my help as much as I need his. I've got to whip up a base medium with similar...\n\n...You know what, I'm not going to bother rambling about the details. Just bring me the Shadraspawn eggs from Agol'watha. There should be quite a few, guarded by the Vilebranch trolls.", progress = "I hope you brought enough.", completion = "Good, good. Just put them over there, I've got my hands full.", objectives = "Collect 5 Shadraspawn Eggs from Agol'watha.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26383] = { id = 26383, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking Waves of Change", description = "You! You look able. And perhaps willing to help?\n\nAuberdine has finally fallen. Though many of its inhabitants departed long ago when the city first suffered the brunt of the Cataclysm, many of the more stubborn residents are yet unaccounted for. And it now appears that the city may have been overrun by water elementals.\n\nMy sisters need help rescuing the survivors. Please, {class}, use the western tree to reach Rut'theran, then speak to Vesprystus to secure a flight to Lor'danel. Be swift!", completion = "Did the sentinels send you? Thank Elune. We need everyone we can get.", objectives = "Use the teleportation tree in western Darnassus to reach Rut'theran Village, then speak to Vesprystus to secure a ride to Lor'danel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26384] = { id = 26384, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkcleric Marnal", description = "We can't toss that tablet aside just yet, {name}. We can use it...\n\nYou see, I'm quite taken with the venom of the spiders here. It's clearly magical, probably related to that spider-god the trolls are involved with. And if that tablet will allow someone to summon it...\n\nWell, you can see where this is going. The Horde can't pass up this opportunity. Take the tablet to my fellow Forsaken. They're to the west, at the research station in the Hiri'watha ruins.", completion = "Ah, what have we here...\n\nFascinating. Quite fascinating.", objectives = "Bring the Tablet of Shadra to Darkcleric Marnal.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26385] = { id = 26385, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking Waves of Change", description = "It seems you have your first charge. You must travel back down to Rut'theran Village, where we first arrived, and speak to Vesprystus to secure a ride to Lor'danel.\n\nOnce in Lor'danel, aid the night elves in any way that you are able. I am trusting you to treat them with the reverence that they deserve in light of all that they have done for us.\n\nI must travel to the distant city of Stormwind to meet with King Anduin. I hope to see your face again very soon, {name}. Until then, a fond farewell.", completion = "Our allies have come to our aid? Thank Elune. Tyrande was wise to extend open arms to your people.\n\nWe need help.  We need everyone we can get.", objectives = "Speak to Vesprystus in Rut'theran Village to secure a ride to Lor'danel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26386] = { id = 26386, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Surkhan", description = "Priestess is not very good at speaking Orcish, no.\n\nMaybe you go speak with Surkhan, upstairs.\n\nTell him about what you've seen inside Zul'Gurub, yes.", completion = "<You explain to Surkhan what has happened up to this point.>\n\nIt would seem that Jin'do has survived, and he is rallying his brothers to once again summon Hakkar into this world.  It was good of you to come to speak with me.\n\nThere is not much we can do now but to wait, and watch.  Jin'do is weak, and prime for striking, but I must wait for word from Rastakhan before issuing orders.  Until then, you and your raptor will have to wait.", objectives = "Report to Surkhan at Bambala in Northern Stranglethorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26387] = { id = 26387, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Starvation Diet", description = "The spiders infesting the Creeping Ruin to the east are useless. We're calling them shadraspawn now, and it's clear they're related to the spider god, but that doesn't change the fact that they're more trouble than they're worth. I'd much rather just wipe the little pests out.\n\nWhen you head to the creeping ruin, destroy any cocoons you find. They feed off the bodies inside for days, so depriving them of their meal will be much more effective than trying to squash them all.", completion = "Now we've got a win-win situation. The spiders are going to either starve off, or find some dwarves and elves to replenish their larder, since my colleagues and I would make a poor meal.", objectives = "Destroy 6 Cocooned Victims at the Creeping Ruins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26388] = { id = 26388, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Skies", description = "Okay, you're all checked in. Wait here for Captain Krazz to bring the zeppelin around, then get on board and accompany the air fleet. Admiral Stonefist will be waiting for you outside of Dragonmaw Port!", completion = "This is a disaster, {name}!\n\nOur air fleet was decimated. And reports are coming in that our navy was attacked - unprovoked - by the Alliance in open water.\n\nAnd what of Hellscream? Is the Warchief dead?", objectives = "Accompany the Horde air fleet to Twilight Highlands. Catch your zeppelin from the tower at the Southern Rocketway Terminus in Azshara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26389] = { id = 26389, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackrock Invasion", description = "The orcs have begun burning down the forest, {name}! They have taken over the vineyard to the east and are planning their final assault against us! They must be stopped!\n\nHead east, across the river, and kill the rampaging Blackrock orcs. Collect their weapons as proof of their demise and return to me.\n\nYou're our only hope, {name}!", progress = "Have you killed the rampaging orc hordes?", completion = "The Blackrock orcs will surely fall now that their main force has been defeated! Only one task remains.", objectives = "Recover 8 Blackrock Orc Weapons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26390] = { id = 26390, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ending the Invasion!", description = "The rampaging orc horde is led by a savage beast known as Kurtok the Slayer! Kurtok is responsible for the recent invasion and must be killed if we are to have peace in the valley.\n\nVenture back east, across the river and through the vineyard, and look for the passage leading into the mountains. Kurtok will be there, preparing for another assault. Kill him and return to me.", progress = "Have you found Kurtok?", completion = "With Kurtok slain we are safe once again from the orcish hordes. I will send peasants to the pass in an attempt to seal the passage so that no more orcs may come through into our territory.\n\nYou have the thanks of Stormwind and of the Alliance, hero!", objectives = "Kill Kurtok the Slayer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26391] = { id = 26391, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Extinguishing Hope", description = "Times like these make me long for when the Defias were still around. The cataclysm has opened a pathway from the Burning Steppes and now Blackrock orcs pour into Northshire Valley! They have taken over my vineyard and are burning it to the ground! TO THE GROUND!\n\nPlease, {name}, that vineyard is all I have. Take my fire extinguisher and extinguish the flames at the vineyard. There still might be hope for that land!", progress = "Have you put out the fires?", completion = "Bless your heart, {name}. You truly are a hero of the Alliance! Though the land is completely incinerated and there is nothing left of the vineyard but ash and debris, I still might be able to recover. Right? How bad can it be?", objectives = "Use Milly's Extinguisher to put out 8 Vineyard Fires.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26392] = { id = 26392, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voucher of Bravery", description = "You've driven off the Blackrock orcs, and for that we are grateful! Though the vineyards have been burned to the ground, the rest of Northshire is safe, thanks to you.\n\nPlease accept this voucher outlining your bravery and deliver it to Marshal McBride. He is responsible for the safety of Northshire and he will be happy to hear about what you have done.", objectives = "Deliver the Voucher of Bravery to Marshal McBride at Northshire Valley in Elwynn Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26393] = { id = 26393, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Swift Message", description = "Although we don't get much aid from Stormwind directly, I do have a contact in the city who helps supply us with armor.  His name is Osric Strang.  His shop, Limited Immunity, is in the Old Town of Stormwind.\n\nOur supply of armor dwindles, and I must contact Osric for more.  Can you take him this note?\n\nThe fastest way to Stormwind is through Bartlett the Brave, our gryphon master.  He's just outside of the smithy; bring him my note, and then take a gryphon to Stormwind.", progress = "You look like you're in a hurry.  Well, then you came to the right place!", completion = "You have to get this note to Stormwind?  That's not a problem, you can take one of my gryphons!", objectives = "Bring Argus' Note to Bartlett the Brave the gryphon master.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26394] = { id = 26394, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Continue to Stormwind", description = "For a small fee, you can take a gryphon to Stormwind, so you can deliver Argus' note to Osric.  You won't get there faster any other way.\n\nIf that sounds acceptable, then just speak to me again when you're ready for the ride.  I'll charge you a little, but trust me; it'll be worth it!", progress = "You've been traveling, eh?  Have you been anywhere interesting?", completion = "Ah, a note from Smith Argus?  I'm not surprised he needs more gear.  There are so many new recruits these days.\n\nWell thank you, {name}.  Here's some money to cover your travel costs.", objectives = "Buy a gryphon ride from the gryphon master Bartlett the Brave, then bring Argus' Note to Osric Strang, in the shop Limited Immunity, in the Old Town of Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26395] = { id = 26395, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dungar Longdrink", description = "{name}, I gathered into this crate everything Argus asked for.  Can you take it to him?\n\nIf you've already spoken to Bartlett at Goldshire, then you can take a gryphon back to him.  Dungar Longdrink is our gryphon master, over in the trade district.\n\nSpeak with Dungar, then get this crate to Argus as fast as you can.  We don't want our fighting men and women in Goldshire to go without fresh equipment!", progress = "Is that sweat on your brow, lad?  You've been running too much.  Next time, take a gryphon!", completion = "A crate for Goldshire, eh?  People sure are getting lazy. Have you been to Goldshire before?  If so, then it's no problem, my friend.  I have plenty of gryphons trained to fly that route!", objectives = "Bring Osric's Crate to Dungar Longdrink the gryphon master.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26396] = { id = 26396, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Argus", description = "The gryphon master in Goldshire is Bartlett.  If you've spoken to him before, then you can take one of my gryphons to him.\n\nThat's a good lesson to know: gryphons are always trained to fly to their capital city, but they'll only take you to a remote gryphon master after you've already been there.\n\nYou've already been to Bartlett, so just speak with me again when you're ready to take a gryphon to Goldshire.  Once there, you can deliver Osric's Crate to Smith Argus.", progress = "You're back from Stormwind?  Did Osric send the armor?", completion = "Great, you brought the armor!  We'll get this divvied to those who need it immediately.\n\nThank you, {name}.  Your efforts have been a great help to us.  And now that you're no stranger to gryphons, I hope you'll come and lend your aid to Goldshire often!", objectives = "Buy a gryphon ride to Goldshire from the gryphon master Dungar Longdrink, then take Osric's Crate to Smith Argus at Goldshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26397] = { id = 26397, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Walk With The Earth Mother", description = "Much has changed outside of Mulgore, {name}. The world is torn, and our Horde allies have turned down dark paths. We must guide them. Even in the darkest hour, we will bravely hold our heads high, and honor the Earth Mother in all we do.\n\nYou must go, {name}, and be this example. Go to Orgrimmar. Tell Saurfang how the Grimtotem were driven out. Let him know our pride and discipline, our strength and sorrow.\n\nTal at the Skytower will send you on your way. Go in peace, and never forget your people.", progress = "What makes you seek the Warchief of the Horde, {race}?", completion = "The Grimtotem forced from Mulgore... if Baine speaks for this, you are indeed a fierce warrior.\n\nFrom this day, your strength is no longer your own. It belongs to me, and the Horde, as a weapon of war.\n\nHellscream's eyes are upon you, {name}. Victory or death!", objectives = "Take the Mark of Bloodhoof to High Overlord Saurfang, located in Grommash Hold in Orgrimmar.\n\nYou may speak with Tal the Wind Rider Master to travel there, or wait for the zeppelin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26398] = { id = 26398, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Walk With The Earth Mother", description = "You have fought bravely alongside me, {name}, and done much for my people. If every {race} could be as noble, the future of the Horde might not disturb me so much.\n\nI would ask you to ease my worries further. Go to Orgrimmar. Tell High Overlord Saurfang how the Grimtotem were driven out. Let him know our pride and discipline, our strength and sorrow.\n\nTal at the Skytower will send you on your way. Go in peace, friend.", objectives = "Take the Mark of Bloodhoof to High Overlord Saurfang, located in Grommash Hold in Orgrimmar.\n\nYou may speak with Tal the Wind Rider Master to travel there, or wait for the zeppelin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26399] = { id = 26399, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mosh'Ogg Bounty", description = "Say... have you heard about the ogres?  I got a hot tip from some fella' named Mok'thardin that some {race} schmuck in a ridiculous {class} getup found this ogre hand, and...\n\n<Skeezy trails off as he looks you over.>\n\nWhat was I just saying?  Oh yes... some <SWASHBUCKLING HERO/BREATHTAKING HEROINE> found this ogre hand, and Mok'thardin thinks it means that the ogres have some special artifact.  I've seen them guarding a chest up in some ruins behind their mound.  Care to fetch it for me?", progress = "Why is it that the OGRES always find the priceless artifacts?", completion = "<Skeezy struggles fruitlessly to open the box.>\n\nThose ogres really know how to close a treasure chest, I'll tell you what.  A box is useless to me, hero.  We're going to need to find a way into this crate.", objectives = "Obtain the Mosh'Ogg Bounty from the ruins behind the Mosh'Ogg Ogre Mound.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26400] = { id = 26400, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Universal Key", description = "We're going to need something even stronger than those beefy {race} hands of yours to open this.  And the Venture Company schlubs to the northwest might have just the thing.\n\nLast time I was over there, I saw shredders walking around with giant rotating blades on their hands.  That's one way to open a box!\n\nIf you can't find any shredders, you might also try the giant sawblade in their lumber mill, by the lake.", progress = "You get that chest open yet?  I can't wait to see what's inside.", completion = "<The goblin peers inside.>\n\nWhaaaaaa?!?\n\nI'm... I'm going to have to send this to... to Flem... in the south.  He'll know what to do with it.", objectives = "Open the Mosh'Ogg Bounty by fighting a Venture Co. Shredder or by using the sawblade in the Venture Company lumber mill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26401] = { id = 26401, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Vestia", description = "The soft glow from the pedestal brightens, and you can see a simple chain left behind. Is this what the apprentice was searching for?", progress = "You're back... and without him...", completion = "How horrible... for someone so young and full of promise to fall to demons!\n\nI beg your forgiveness for sending you into danger as well, {name}. I hope you don't cross paths with that demoness again...", objectives = "Bring the Darkmist Amulet to Vestia Moonspear at the Tower of Estulan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26402] = { id = 26402, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "General Shandris Feathermoon", description = "We druids do not keep very close company with the Sentinel army, but we are always willing to work together to defend our lands. Now that you have assisted me, I would be remiss in not requesting you assist them as well.\n\nShandris Feathermoon, general of the Sentinels, commands the war effort for all of Kalimdor from the newly built Feathermoon Stronghold to the south. Tell her I sent you; I am sure she will have need of your skills.", completion = "Telaron has already sent word of you, {name}. I'm interested in seeing if you're half as skilled as he claims.\n\nI am fighting a war on multiple fronts, while keeping our currently held areas properly defended, as well as overseeing the instruction of our youngest sentinels. If you're a decent fighter, there will be plenty for you to do.", objectives = "Speak with Shandris Feathermoon at Feathermoon Stronghold in Feralas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26403] = { id = 26403, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Venture Company Mining", description = "Man, I hate the Venture Company.  They have a string of operations through Stranglethorn which keeps hard-working goblins, like me, from making honest gold!\n\nMy way? Theft. The Venture Co. geologists near Lake Nazferiti to the northwest are deeply interested in those strange blue crystals they have been finding in the mines.  Bring me samples of the stone from their geologists.  I don't care what you have to do to get them.", progress = "Do you have those crystals??  I need them!!\n\nI mean...I need to know the evil Venture Company is losing ground in Stranglethorn.  Because, you know, we honest folk have to make a living!", completion = "Great!  Wonderful!  I can get a bundle for these!!\n\nThat Venture Company sure picked the wrong jungle to mine in, didn't they?  We'd all be in better shape if they moved out of here.", objectives = "Bring 5 Tumbled Crystals to Skeezy Whillzap at Bambala in Northern Stranglethorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26404] = { id = 26404, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Above My Pay Grade", description = "Hey, have you been to Hardwrench Hideaway yet?  Oh, you've GOT to see it.  It's everything a goblin could ever hope for.\n\nTell you what... you look like a stand-up {class}.  Raskha in the vest and the skirt over here can give you a ride, if you don't already know the way.\n\nThe flight's on me.", completion = "Skeezy sent you to the right place.  Welcome to Hardwrench Hideaway!", objectives = "Report to Sassy Hardwrench at Hardwrench Hideaway in the Cape of Stranglethorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26405] = { id = 26405, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zul'Mamwe Mambo", description = "The Skullsplitters are an embarrassment to the troll empire.  Their petty squabbles with the Bloodscalps have torn Northern Stranglethorn apart.  Where tribes like the Darkspear and the Zandalari thrive, the Skullsplitters fight over ruins.\n\nI have been authorized to issue rewards to mercenaries who are willing to deliver punishment to the Skullsplitters.  I encourage you, and anyone you know, to travel south to Zul'Mamwe and cull their wayward tribe.", completion = "As promised, your reward.  You do the troll nation proud.", objectives = "Kill 16 Skullsplitter Trolls within Zul'Mamwe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26406] = { id = 26406, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fang of Shadra", description = "We'll need the Fang of Shadra next.\n\nIt's kept in the Creeping Ruins to the east, guarded by Shadra's own spawn.  Their venom is strong, {name}... don't get careless.", progress = "Have you got the fang?", completion = "There it is... only one left.", objectives = "Collect the Fang of Shadra from the Creeping Ruins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26407] = { id = 26407, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mosh'Ogg Handiwork", description = "This ogre was carrying an unusual item: the severed hand of another ogre, tied to a piece of string, and worn around the neck.  The hand itself is marked heavily with scars that glow a faint purple.\n\nA scar that glows after death is highly unusual, and to find such an item on an ogre is even stranger.  Perhaps someone back at Grom'gol will know what to do with this oddity.", progress = "A hand, you say?", completion = "<The Far Seer makes sure to hold the item by the string, carefully avoiding the dead ogre's fist.>\n\nStrange indeed.  I will pass this on to my contacts in the east, near the Mosh'Ogg's main camp.  I have a feeling that they'll be interested in these strange scars.\n\nYou have my thanks, {race}.", objectives = "Bring the Disfigured Mosh'Ogg Hand to Far Seer Mok'thardin at Grom'Gol Base Camp in Northern Stranglethorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26408] = { id = 26408, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashes in Ashenvale", description = "Darkshore may be battered and broken, but thanks to you, we've achieved some amount of safety here. Some amount of peace. We've much rebuilding to do.\n\nYou should continue on, friend. Garrosh has pressed the full might of his Horde against us in Ashenvale. They will kill all of us and chop the forest clear if we don't step forward to stop them.\n\nIf we are to have any hope of not losing those forests entirely, we'll need your help. Follow the road to the south and find Sentinel Shyela.", completion = "Good to see a new face around here!\n\nThe forest crawls with Horde, but my assignment requires that I keep this outpost safe. I could really use someone who might be up for a good fight.", objectives = "Speak to Sentinel Shyela at Orendil's Retreat in Ashenvale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26409] = { id = 26409, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where's Goldmine?", description = "My goblin initiate has been gone for quite some time. His name is Goldmine.\n\nI sent him out to observe the local rock flayers southwest at the Quartzite Basin. Perhaps you would be willing to find him? When you do, please ask him to come back to the temple.", completion = "Hiya! Lend a hand, would ya, bub?", objectives = "Find Initiate Goldmine at the Quartzite Basin in Deepholm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26410] = { id = 26410, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Explosive Bonding Compound", description = "This guy's the son of the Earthen leader! He almost made it to the temple when he got ambushed by more rock flayers than I can count!\n\nWe know that the Earthen Stonefather has the middle fragment of the World Pillar. Maybe if we were to heal his son, the Stonefather would give us the fragment?\n\nMy heals won't work on Flint here. But if we were to get some of the quartzite resin off of these monsters, I think I can make an explosive compound that will bond and cauterize his wounds.", progress = "It won't take much resin. Those rock flayers are pretty dangerous though.", completion = "Good thing that I just happen to be a grand master of all things explosively alchemical.\n\nThis won't ignite on its own, though.", objectives = "Collect 5 Quartzite Resin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26411] = { id = 26411, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Apply and Flash Dry", description = "Alright, take this and apply it to his wounds. If the cauterizing effect of the flash dry explosion doesn't crack him wide open, it should completely heal him.\n\nI think.", progress = "Don't yap at me. Use the explosive bonding compound on Flint.", completion = "Looks like that did it. He should come to any moment now.\n\nI told you I was a grand master of alchemy!\n\nI've got some extra resin leftover. I can make it into all kinds of explosively wonderful stuff. What do you want?", objectives = "Use the Explosive Bonding Compound on Flint Oremantle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26412] = { id = 26412, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mosh'Ogg Bounty", description = "Say... have you heard about the ogres?  I got a hot tip from some fella' named Mok'thardin that they're hiding some special, magical artifact in their cave.  Skeezy knows better, though.  I can smell money from a Mulgore mile away, and I'll bet that ogre doodad's worth a fortune.\n\nHere's a hint: I've seen them guarding a chest up in some ruins behind their mound.  Care to fetch it for me?", objectives = "Obtain the Mosh'Ogg Bounty from the ruins behind the Mosh'Ogg Ogre Mound.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26413] = { id = 26413, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Take Him to the Earthcaller", description = "He still looks a little loopy to me. His head must still be ringing.\n\nBest get him inside the temple and see what the Earthcaller wants to do with him.\n\nI think I'm going to stay out here a little while longer and \"observe\" these rock flayers.", progress = "One of the Earthen? This is an unexpected and fortuitous surprise, {name}.", completion = "We are honored by Flint Oremantle's presence. I am given to understand that the Stonefather is in possession of a fragment of the World Pillar.\n\nIt is imperative that we recover all of the fragments. The instability between worlds is increasing. Soon it may become too great even for mighty Thrall to hold at bay.", objectives = "Introduce Flint Oremantle to Earthcaller Yevaa at the Temple of Earth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26414] = { id = 26414, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hitting a Walleye", description = "Sometimes, I fish for fun.  Other times to relax, but sometimes I want a challenge.  That's where the hardened walleye comes into the picture.  This prized fish is not caught for us to eat, but for the challenge.  You can find the walleye in Stormwind Lake just north of the city.  Think you are up to the challenge?", progress = "Was the challenge too much for you?", completion = "Nice work {name}!  I see you are quite the fisherman these days.  Might just have to take you out on the boat soon and see what you can really do!", objectives = "Catherine Leland in Stormwind City wants you to bring her 8 Hardened Walleye.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26415] = { id = 26415, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Questflag for Captain's Log" }
quests[26416] = { id = 26416, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Well, Come to the Jungle", description = "My commander has sent me to scout for potential recruits to assist in the defense of Grom'gol Base Camp in Northern Stranglethorn.  Are you familiar with Stranglethorn?  It's a long way away... across the Great Sea, on the southern tip of the Eastern Kingdoms.  You fit the build he was looking for... interested in leaving Kalimdor for a while?\n\nIf so, then go talk to my cohort Bort in Orgrimmar.  He'll help you board the zeppelin.\n\nAnd tell him I said \"Woozle wozzle.\"  He'll know what it means.", completion = "Hah!  That Cromula cracks me up.\n\nOh, right, Stranglethorn.  You're really going?", objectives = "Report to Bort in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26417] = { id = 26417, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Northern Stranglethorn: The Fallen Empire", description = "Commander Aggro'gosh is looking for devoted members of the Horde to assist him and his mission in Grom'gol.  If you're interested, just hop on up to the top of that zeppelin tower and board the Grom'gol zeppelin.  It's that easy!\n\nSeriously, Stranglethorn is the place to be right now... there's plenty of action to be found, and not nearly as much cataclysmic damage as, say... Stonetalon Mountains.  I wish I could go with you.", completion = "Glad you could make it!  Let's get to work, shall we?", objectives = "Report to Commander Aggro'gosh at Grom'gol Base Camp in Northern Stranglethorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26418] = { id = 26418, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shell of Shadra", description = "We've one last part to collect, and then we'll have everything we need.\n\nThe Shell of Shadra is held by the spider god's last living high priestess, Qiaga the Keeper. She stands atop the Altar of Zul, guarded by other fanatical zealots.\n\nSimple enough, no? Get up the steps of the altar and send her head rolling back down them. Bring the shell to me and we will have Shadra at last.", progress = "Do you have it?", completion = "Yes... it's finally time. Shadra will be ours!", objectives = "Kill Qiaga the Keeper and collect the Shell of Shadra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26419] = { id = 26419, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadra the Venom Queen", description = "<The ground rumbles as the idol sits on the altar, and the lake below roils! Shadra is emerging!>", completion = "Excellently done. You have served the Dark Lady well today, {name}.\n\nThis virulent blood will supply our armies with all manner of powerful weapons against the disgusting Alliance. We will wipe them from these lands.\n\nFor the Horde, of course... and all thanks to you.", objectives = "Kill Shadra the Venom Queen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26420] = { id = 26420, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diggin' For Worms", description = "Hey there, Angler!  Arnold here tells me that you have been looking for a new fishing spot and I think I know just the place.  North of Stormwind there is a great little spot called Olivia's Pond.\n\nThe pond is stocked with crystal bass every year but they are hard to catch.  They only bite on a very specific type of bait... overgrown earthworms.  If you search the shore around the pond, you should find plenty of worms to use as bait.", progress = "Did the bait work?", completion = "Those look like some nice bass, {name}.  Let's fry em' up and see how they taste!", objectives = "Find an Overgrown Earthworm near Olivia's Pond and use it as bait to catch a Crystal Bass. Crystal Bass can be found in Olivia's Pond, north of Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26421] = { id = 26421, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet the High Tinker", description = "I don't know if you'll remember Mekkatorque or not. Nevin tells me that memory loss is pretty common for a Gnomeregan survivor.\n\nMekkatorque, or more properly, the High Tinker Mekkatorque is the leader of all the gnomes. He has made a habit of meeting with every rescued survivor personally. You should introduce yourself to him. He'll be with his war council beneath the tent in the center of town.", completion = "It's good to meet you, {name}. You've probably heard others speaking of Operation: Gnomeregan. Let me tell you a bit about what happened and why we left the dwarven city of Ironforge.", objectives = "Introduce yourself to High Tinker Mekkatorque in New Tinkertown.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26422] = { id = 26422, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet the High Tinker", description = "I don't know if you'll remember Mekkatorque or not. Nevin tells me that memory loss is pretty common for a Gnomeregan survivor.\n\nMekkatorque, or more properly, the High Tinker Mekkatorque is the leader of all the gnomes. He has made a habit of meeting with every rescued survivor personally. You should introduce yourself to him. He'll be with his war council beneath the tent in the center of town.", completion = "It's good to meet you, {name}. You've probably heard others speaking of Operation: Gnomeregan. Let me tell you a bit about what happened and why we left the dwarven city of Ironforge.", objectives = "Introduce yourself to High Tinker Mekkatorque in New Tinkertown.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26423] = { id = 26423, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet the High Tinker", description = "I don't know if you'll remember Mekkatorque or not. Nevin tells me that memory loss is pretty common for a Gnomeregan survivor.\n\nMekkatorque, or more properly, the High Tinker Mekkatorque is the leader of all the gnomes. He has made a habit of meeting with every rescued survivor personally. You should introduce yourself to him. He'll be with his war council beneath the tent in the center of town.", completion = "It's good to meet you, {name}. You've probably heard others speaking of Operation: Gnomeregan. Let me tell you a bit about what happened and why we left the dwarven city of Ironforge.", objectives = "Introduce yourself to High Tinker Mekkatorque in New Tinkertown.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26424] = { id = 26424, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet the High Tinker", description = "I don't know if you'll remember Mekkatorque or not. Nevin tells me that memory loss is pretty common for a Gnomeregan survivor.\n\nMekkatorque, or more properly, the High Tinker Mekkatorque is the leader of all the gnomes. He has made a habit of meeting with every rescued survivor personally. You should introduce yourself to him. He'll be with his war council beneath the tent in the center of town.", completion = "It's good to meet you, {name}. You've probably heard others speaking of Operation: Gnomeregan. Let me tell you a bit about what happened and why we left the dwarven city of Ironforge.", objectives = "Introduce yourself to High Tinker Mekkatorque in New Tinkertown.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26425] = { id = 26425, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet the High Tinker", description = "I don't know if you'll remember Mekkatorque or not. Nevin tells me that memory loss is pretty common for a Gnomeregan survivor.\n\nMekkatorque, or more properly, the High Tinker Mekkatorque is the leader of all the gnomes. He has made a habit of meeting with every rescued survivor personally. You should introduce yourself to him. He'll be with his war council beneath the tent in the center of town.", completion = "It's good to meet you, {name}. You've probably heard others speaking of Operation: Gnomeregan. Let me tell you a bit about what happened and why we left the dwarven city of Ironforge.", objectives = "Introduce yourself to High Tinker Mekkatorque in New Tinkertown.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26426] = { id = 26426, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Violent Gale", description = "There is a task that I can set before you.\n\nIt is a dangerous task. Completing it will help impress the more stubborn Stone Lords.\n\nTo the northwest is the Scoured Reach. Severe winds batter the rock and hide the true living threat underneath.\n\nWithin the Scoured Reach are Gyreworms. They devour rock and move through it as if it were water. They do the same thing to our rocky skin.\n\nFind Felsen the Enduring. Have him direct you to the Crumbling Depths. I will speak to you once you get that far.", completion = "<The ground rumbles slightly as you approach the cave. This looks to be the entrance that Diamant and Felsen spoke of.>", objectives = "Find Felsen the Enduring and follow his instruction towards the entrance to the Crumbling Depths.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26427] = { id = 26427, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Without a Captain or Crew", description = "Not sure who you're with, but you don't look like one of... them.\n\nI'm not sure what happened.  I slept through supper and woke up to a ship full of dead people and murderers.\n\nNot sure if you want to kill me or not, but I'll spare you the trouble.\n\n<Moody points to a wound in his stomach.  His insides are not where they should be.>\n\nI can keep steering the ship for a while longer.  You don't die from a gut wound immediately.  Just bring me some rope and some rum... no, whiskey.", progress = "You have what I asked for?", completion = "All right, help me get tied to the wheel.\n\n<Moody sips from the bottle.>", objectives = "Bring First Mate Moody a Bottle of Whiskey and a Spool of Rope.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26428] = { id = 26428, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Steal From Thieves", description = "The harlot! The swine! Kenata still lives; her family healthy and prospering while I suffer. Forsaken indeed!\n\nMy family is gone, taken by the plague. Our estate also forfeit; looted and burned during the war. And after all that, she and her lousy children had the audacity to steal the only precious belongings I had left.\n\nI don't care about the things they stole any more. What I want now are their heads!\n\nKill them for me! Go to the Dabyrie Farmstead in Arathi, northeast of Refuge Point.", progress = "Kill them all and bring me their heads!", completion = "You stand before me as a figure of vengeance, and I bow down before you in thanks.\n\nWith that cow's death, and knowing that their seed will no longer spread over the face of Azeroth, I can put my energy into something more lucrative. I hope you looted their farmstead after you finished them off.", objectives = "Take the heads of Kenata Dabyrie, Fardel Dabyrie, and Marcel Dabyrie.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26429] = { id = 26429, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crush the Witherbark", description = "The Witherbark trolls and Boulderfist ogres of Arathi are working together to rid us from this land, but we shall not meet our fates at their, or anyone else's, hand. We will slay them and show them that we, too, have a home here. \n\nThe trolls turned their backs to us; the ogres would use us for food and bedding if we allowed them to--these things shall not be.\n\nWe start our attack on the Witherbark trolls to the south of here. Slay them in droves, and only return when their camps run thick with blood.", completion = "The signs of war are upon your garments, and sweat drips from your brow. Good, very good indeed.", objectives = "Slay 10 Witherbark Axe Throwers, 10 Headhunters and 8 Witch Doctors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26430] = { id = 26430, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Revantusk Village", description = "Not all forest trolls are foul nuisances like the Witherbark. North of here in the Hinterlands is Revantusk Village, home to the only forest troll tribe still allied with the Horde.\n\nEven they cannot escape the cruelty of their brethren. The Vilebranch tribe wars with them, distracting them from our battle with the Alliance.\n\nYou have fought well here. Speak with Urda if you wish to fly to Revantusk. Their village will have use of your strength.", completion = "Welcome to Revantusk, {class}. I hope fighting the Witherbark hasn't exhausted you; the Vilebranch are even worse.", objectives = "Travel to Revantusk Village in The Hinterlands and speak with Elder Torntusk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26431] = { id = 26431, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archaeology", description = "Accept this quest to find archaeology points on your map!" }
quests[26432] = { id = 26432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fall of Jintha'Alor", description = "We've got more to deal with than just dwarves, mon. While I watch the village, my mate Primal Torntusk has gone to lead our warriors against the wicked Vilebranch tribe.\n\nThey've killed our brothers, and I was even taken prisoner by them once. No more! This time, the city of Jintha'Alor falls to us.\n\nGo to Jintha'Alor and speak with my mate. She's captured a camp near the entrance to the city.", completion = "Welcome, {class}. We're gonna make the Vilebranch regret ever crossin' us.", objectives = "Find Primal Torntusk at Jintha'Alor in The Hinterlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26433] = { id = 26433, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Holy Water of Clarity", description = "Skeezy said you'd be coming.  Let's identify this... thing.\n\nTo start out, I'm going to need you to obtain The Holy Water of Clarity.  The nagas to our southeast maintain a hallowed shrine that dispenses a water so clean, so fresh, and so mouthwateringly pure, that when the imbiber quaffs but a mouthful of the sacred stuff, their mind is cleansed and their best path made clear.\n\nSounds good, doesn't it?\n\nObtain it from the Nek'mani Wellspring at the peak of the naga camp.  Good luck!", progress = "<Flem's ears perk up as you approach.>\n\nThe Holy Water of Clarity?  Is it here!?", completion = "<The goblin downs the water in one gulp.>\n\nAhh... do you know how hard it is to get fresh water in Stranglethorn?  It's no wonder that the nagas guard their shrine so ferociously!\n\nOh, right... your artifact, and clarity.  Clarity...\n\nI've got it!", objectives = "Obtain The Holy Water of Clarity from the Nek'mani Wellspring in the Cape of Stranglethorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26434] = { id = 26434, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Primal Reagents of Power", description = "I see clearly now... the key to identifying this mysterious talisman revolves around obtaining some rare and precious items.  These Primal Reagents of Power, when properly combined, will reveal to us the origin of our treasure.\n\nTravel north, to the western side of the Gurubashi Arena, and hunt the cats that roam the jungle.  Their fleecy furs will lead us to the truth!", progress = "Make sure the reagents are extra-cushy, {name}.  A scratchy reagent simply won't do.", completion = "<Flem feels the hides and smiles to himself.>\n\nExcellent work, {name}!  These reagents will serve perfectly.", objectives = "Obtain 4 Supple Tiger Furs and 4 Velvety Panther Furs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26435] = { id = 26435, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I'm A Huge Liar and a Fraud", description = "I have no idea what this artifact is.  I have no idea where I would even START finding out what it is.\n\nIn fact, I have no idea why anybody expected ME to be able to identify it in the first place.\n\nI asked for water because I was thirsty.  I asked for the jewelry and furs for... well, they're for my girlfriend.\n\nHopefully I can at least point you in the right direction.  Garley Lightrider in Booty Bay is a member of the Reliquary, and might be of more use than me.\n\nSorry.", progress = "Yes, {race}?  I'm quite busy.", completion = "Fascinating!\n\nI'll need some time to study this.  Why don't you have a look around Booty Bay and come back later?", objectives = "Bring the Opened Mosh'ogg Bounty to Garley Lightrider at Booty Bay in the Cape of Stranglethorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26436] = { id = 26436, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entrenched", description = "Your intentions appear true.\n\nI will impress upon the other Stone Lords my wary trust.\n\nWith this, they should speak to you.\n\nMore importantly, they should listen.\n\nEarning their favor may take time. Earning the Stonemother's favor may take more time. Time is a potent offering, so be generous with it.\n\nAmong the Shuddering Spires far to the northwest, you shall find Kor the Immovable. He is evenly tempered. His situation lends itself well to seeking outside aid.\n\nGo to him.", completion = "Diamant says you are to be trusted. Diamant is patient and wise, so I shall allow you to prove yourself.\n\nAs it happens, I could use hands that are more... mobile.", objectives = "Seek out Kor the Immovable among the Shuddering Spires.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26437] = { id = 26437, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making Things Crystal Clear", description = "Among the Shuddering Spires are crystals. White, chalky crystals. We can absorb these crystals into our skin. To cleanse us. Purify us.\n\nI do not stride among the stones any longer. I am one with the earth. This carries many boons, but I can no longer retrieve the crystals for myself.\n\nBring me the crystals that I might be stronger. Carry them away from the flayers. Away from my sons. This honor should be mine.", progress = "Have you done this favor that I asked of you? Did you bring the crystals?", completion = "Ahh... invigorating. Thank you, fleshling.", objectives = "Collect 8 Chalky Crystal Formations.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26438] = { id = 26438, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Intervention", description = "The flayers have gone crazy with hunger. Their digging was once tempered and moderate. Now their hunger cannot be quenched. They grow murderously violent.\n\nThe flayers have turned on my sons. They overwhelm them. Kill them. It must stop.\n\nKill the flayers. They serve no purpose to the earth. Their passing will not be missed. Save my sons. Slaughter any flayers you find.", completion = "You've proven useful, {race}.", objectives = "Kill 12 Jaspertip rockflayers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26439] = { id = 26439, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Putting the Pieces Together", description = "{race}. If you act in the service of the Stone Lords, there are those that might aid you.\n\nWatch for the Stonebound. They lie dormant all around the Shuddering Spires. It should not take much prompting to rebind them to service against the flayers.", progress = "<Berracite grumbles, and you feel the reverberations gradually roll by under your feet.>", completion = "Thank you, {race}.", objectives = "Aid 6 Dormant Stonebound Elementals in reforming.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26440] = { id = 26440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clingy", description = "<A miniscule elemental seems to have taken a liking to you.>\n\nCaris... carstr... crystal? <Pebble looks up at you expectantly.>\n\n<You did notice a very large crystal formation towards the middle of the Shuddering Spires. Perhaps you should take him there?>", progress = "<Pebble looks up at you expectantly.>", completion = "<The stones in Pebble's body bounce up and down happily. He seems very appreciative.>", objectives = "Bring Pebble to the large crystal formation in the Shuddering Spires.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26441] = { id = 26441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "So Big, So Round...", description = "<Pebble looks around, excited by something. After a few seconds of confusion, he stops and stares up at you with big, glowy gem eyes.>\n\nHug-nery... hungry...\n\n<Try as you might, there's no resisting those eyes. Maybe Kor knows what mini-mentals like to eat?>", sourceObjective = "Speak to Kor to find out what kind of food Pebble might like.", completion = "You've made a friend, have you?\n\nAre you certain you want to feed him? He might become attached.", sourceObjectiveStatus = "unverified-source-field" }
quests[26442] = { id = 26442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rock Lobster", description = "If I could choose my last meal, it would definitely be fresh lobster tail.  Something about that tasty crustacean is just irresistible!  We recently started trapping lobsters here in Stormwind.  Would you mind heading out and checking the traps for me?\n\nOne more thing, watch out for the sharks.  They can be vicious down there.", progress = "Looks like you were able to avoid the sharks.  Were there any lobsters in the traps?", completion = "Looks like the traps are working!  Thanks {name}!", objectives = "Collect 6 Rock Lobsters from the cages below the docks in Stormwind Harbor. Watch out for sharks!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26443] = { id = 26443, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diabolical Plans", description = "The demon dropped this parchment, which is amazingly written in the Common tongue!  The ones mentioned in it, Diathorus and Gorgannon, are the two infamous dreadlords that control the demons hereabouts.\n\nThe plans detail preparations for a demonic attack on Forest Song to the north, the location where a new draenei settlement is being established.\n\nPerhaps Vindicator Vedaar at the Warsong Lumber Camp would be interested in these?", progress = "What do you have there, sir?", completion = "By the Seven Crystals of Ata'mal, this cannot be! They plan to attack Forest Song?!\n\nNot on my watch!\n\n<Vindicator Vedaar crumples the demon-scrawled plans in his fist.>\n\nNo. We will not allow this to happen!", objectives = "Deliver the Diabolical Plans to Vindicator Vedaar at the Warsong Lumber Camp in Ashenvale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26444] = { id = 26444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Destroy the Legion", description = "I will not tolerate their existence on this world! The Burning Legion all but destroyed our race and we fell back to settle a new home on a new world. Then they came again and we retreated, over and over.\n\nNo more!\n\nThere is a remnant of the Legion to the south and west in the regions known as Felfire Hill, Demon Fall Canyon and Demon Fall Ridge. They are what is leftover from a force that once long ago invaded this world.\n\nGo and destroy as many as you can before it is too late!", completion = "You have my respect and thanks, {class}. Perhaps we'll be able to create a new home here without having to worry about the Burning Legion yet again.", objectives = "Slay any 15 demons at Felfire Hill, Demon Fall Canyon, and Demon Fall Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26445] = { id = 26445, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Never Again!", description = "{name}, it falls to you to see that this attack by the Burning Legion never comes to pass. You must go and slay their leaders.  Without them the demons will be mindless.\n\nYou will find Gorgannon in Demon Fall Canyon south beyond Felfire Hill, near Mannoroth's floating, broken spear.\n\nDiathorus the Seeker resides somewhere in the barrow den atop Demon Fall Ridge. To find the ridge, look for a ramp up from Demon Fall Canyon near the Horde's monument to Grom Hellscream.\n\nBring me their weapons.", progress = "Our night elf scouts report that preparations for the attack are almost complete. Those dreadlords must die soon, {name}!", completion = "Never again will the Burning Legion threaten Ashenvale! You have delivered us from a fight we very likely would have lost, {class}.\n\nI give you thanks, {name}, and the deepest gratitude of the Hand of Argus. It honors me to have you at our side!", objectives = "Obtain Gorgannon's Flaming Blade and the Seeker's Fel Spear.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26446] = { id = 26446, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reclaiming Felfire Hill", description = "Little one, to the southwest is an area of Nightsong Woods that has in recent times come to be called Felfire Hill. It is very sad to see the demons crawling over it, spreading their corruption.\n\nWould you do something to help take back the land?\n\nI have a number of seeds that I have been saving for such a purpose. Take them to Felfire Hill and plant them in the fertile dirt mounds.", completion = "Good. Though it may take a great deal of your years for the seedlings to grow into ancients, in the fullness of time they will aid us in our fight against all of the enemies of Ashenvale.", objectives = "Plant 8 Tree Seedlings in the Fertile Dirt Mounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26447] = { id = 26447, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diabolical Plans", description = "The demon dropped this parchment, which is amazingly written in the Orcish tongue!  The ones mentioned in it, Diathorus and Gorgannon, are the two infamous dreadlords that control the demons hereabouts.\n\nThe plans detail preparations for a demonic attack on Splintertree Post to the northwest.\n\nYou're certain that Valusha at Splintertree Post would be interested in these.", progress = "What do you have there, scout?", completion = "Dreadlords!  They plan to attack us here at Splintertree Post?!\n\nNot while I still draw breath!\n\n<Valusha crumples the demon-scrawled plans in her fist.>\n\nNo.  We will not allow this to happen!  They are a blight upon our world!", objectives = "Deliver the Diabolical Plans to Valusha at Splintertree Post in Ashenvale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26448] = { id = 26448, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Destroy the Legion", description = "The remains of the demonic Burning Legion have been a thorn in our side for far too long!\n\nNo more!\n\nThe demons are attacking from the areas known as Felfire Hill, Demon Fall Canyon and Demon Fall Ridge to the east.\n\nGo and destroy as many as you can to bring glory to both yourself and the Horde!", completion = "That's better!  There's nothing quite like ridding our world of a demon.  And they make for worthy opponents as well, unlike the weak races of the Alliance.", objectives = "Slay 15 of any demon type at Felfire Hill, Demon Fall Canyon, or Demon Fall Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26449] = { id = 26449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Never Again!", description = "{name}, you will see to it that this attack by the Burning Legion never comes to pass!  Go and slay these dreadlords!  Without them the rest of the demons are essentially mindless.\n\nYou will find Gorgannon in Demon Fall Canyon south beyond Felfire Hill, near Mannoroth's floating, broken spear.\n\nDiathorus the Seeker resides somewhere in the barrow den atop Demon Fall Ridge.\n\nReturn to me with their weapons as proof of your deeds.", progress = "Those dreadlords must die soon, {name}!", completion = "Never again will the Burning Legion make slaves of the orcs, or any other race of the Horde!\n\nBravely fought, {class}!  You have the true heart of the Horde beating inside of you!  You give us much honor!", objectives = "Obtain Gorgannon's Flaming Blade and the Seeker's Fel Spear.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26450] = { id = 26450, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "If They're Just Going to Leave Them Lying Around...", description = "I was just thinking about something, {name}.  Those naga have more than just reeds down there.  They tend to keep little statues lying around on their shrines, in the sand, under their trees.  They don't seem to be USING them.\n\nI could use those statues!  I could... put 'em around the camp, make it feel a little more homey.  Anything's better than a bloody dinosaur corpsepump.  I could sell them as souvenirs.\n\nI could sell them back to the naga!\n\nWhy don't you go grab a couple while I figure this out.", progress = "Let's see 'em!", completion = "Nice work, {name}.  Now I've just got to decide what to do with all of these...", objectives = "Obtain 6 Naga Icons from the Southern Savage Coast in the Cape of Stranglethorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26451] = { id = 26451, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gurubashi Challenge: Free-For-All Arena Combat", description = "The arena is a place of battle unlike any other.  Inside, you have no friends.  Alliances that do form are fleeting, as your allies can turn on you in the blink of an eye.  Horde vs. Alliance, Alliance vs. Alliance, Horde vs. Horde... anything goes.\n\nTake this battle standard, {race}, and place it down on the arena floor.  Defeat the summoned combatant, then return to me.\n\nStay on your toes, {race}.  Anything goes inside the Gurubashi Arena.", progress = "Why don't you get a little bit more blood on your armor before you speak with me again?", completion = "Well done, {race}!  Did you feel it?  The rush of the melee?  The true risk of free-for-all combat?\n\nAs today is your first day here, I'll let you perform in one more competition for another reward.  If you return in the future, you may compete again, once a day.  Your rewards will, of course, improve as you become stronger.", objectives = "Place the Gurubashi Challenge Flag down inside the Battle Ring, then defeat the Gurubashi Arena Challenger.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26452] = { id = 26452, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gurubashi Challenge", description = "You've returned, {race}.  That means you've felt the call of the arena once more.  Very well.\n\nTake this battle standard, {race}, and place it down on the arena floor.  Defeat the summoned combatant, then return to me.\n\nStay on your toes, {race}.  Anything goes inside the Gurubashi Arena.", progress = "Why don't you get a little bit more blood on your armor before you speak with me again?", completion = "Well done, {race}!  I look forward to seeing you fight again soon.", objectives = "Place the Gurubashi Challenge Flag down inside the Battle Ring, then defeat the Gurubashi Arena Challenger.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26453] = { id = 26453, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Helping Hand", description = "Under the supervision of Architect Nemos and Vindicator Vedaar, my people are revitalizing an old night elf outpost in the eastern part of Ashenvale.\n\nThe task of building won't be easy, {name}, for the challenges and enemies they face are many. I know Architect Nemos and his compatriots at Forest Song would appreciate any help they can get, and he has asked me to send any interested <men/women> his way.\n\nSpeak to me again and I will arrange for fast transport for you to their location.", completion = "It's good to see another new arrival here at Forest Song.\n\nVindicator Palanaar is sending as much help as she can muster and each set of hands is appreciated.\n\nTake a look around, {class}. It may not be much now, but with time and help from our night elf allies, we'll build a settlement worthy of calling home. There is much to be done here and any help you can provide would be welcome.", objectives = "Speak with Architect Nemos at Forest Song in Ashenvale.\n\nVindicator Palanaar can offer you a ride to get you there more swiftly.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26454] = { id = 26454, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Shameful Waste", description = "Welcome to Forest Song, {class}. Where you see tents, there will one day be buildings, but such ambition requires a steady stream of materials. I cannot bring myself to order our workers to fell any of the ancient trees of this grove, but our neighbors to the west have no such reverence for the forest.\n\nWe shall reclaim the tainted wood from Satyrnaar to the west. Take the wood to Gnarl at the Warsong Lumber Camp. He is an Ancient who will purify it for our use.", progress = "<The ancient creaks as it turns toward you.>\n\nArchitect Nemos said that you might be bringing wood salvaged from befouled Satyrnaar.", completion = "Wood warped by foul demonic magic is of no use to the draenei at Forest Song. Nothing sound can be built with it, but I shall purify it and return it in good time to Architect Nemos and his people for their use.\n\nSome good will come from this tragedy, after all.", objectives = "Collect 5 Satyrnaar Fel Wood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26455] = { id = 26455, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Chalice", description = "The area to our west, now called Satyrnaar, was once a prominent shrine built by my people. It housed a priceless relic, the Chalice of Elune, entrusted to the shrine's keepers by the priests of Elune. Pilgrims once traveled to the shrine to experience the healing powers the chalice was rumored to hold.\n\nThese stories might be nothing but old wives' tales, but if there is any truth to them, the relic may hold the key to rejuvenating the wounded forest. I must know, {name}.", progress = "Can you feel it, {name}, the touch of corruption upon the wind? If we do nothing, it will continue to advance. That is why I seek the Chalice of Elune. Were you able to find it?", completion = "Excellent work, {name}. There is certainly a latent power here, one that not even constant exposure to the corruption of the satyr can dim.\n\nDo you see how it still shines, after all these years?", objectives = "Obtain the Chalice of Elune.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26456] = { id = 26456, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report from the Northern Front", description = "The battle against the Horde isn't being waged from Raynewood Tower alone, {name}. There's a more substantial Silverwing Sentinel presence at Silverwing Grove to the southeast, near the border with the Barrens. From the grove, Sentinel Farsong directs our efforts against those who would destroy our lands.\n\nI'm a bit late in sending my latest report to her, but also hesitant to leave the tower unattended.\n\nI am in dire need of your help in getting this report to her as soon as possible!", progress = "What's that you have there, {class}?", completion = "Thank you for delivering this report, {class}. From what Sentinel Melyria writes, it seems our worst fears have come to pass. With each advance we make, the Horde appears more determined to do as much damage as possible.\n\nWe can't afford to back down; the fate of our ancestral lands hangs in the balance. With more people like you on the frontlines, I'm certain we could triumph.\n\nWill you join our fight? A new front has just opened in Warsong Gulch to the south.", objectives = "Deliver Sentinel Melyria's report to Sentinel Farsong at Silverwing Grove in Ashenvale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26457] = { id = 26457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agents of Destruction", description = "The Warsong Lumber Camp is a blight upon an embattled landscape. Every time we make progress in halting their operations, Overseer Gorthak orders his loggers to redouble their efforts!\n\nNow, the orcs are cutting more wood than they can possibly use, leaving it to rot while their blades bite into fresh trees! This is an affront to all we stand for, {name}, and we will show them that we'll not suffer further destruction of our lands!\n\nGo, and do not rest until Overseer Gorthak and his minions are dead!", completion = "At last we have sent a message that the orcs won't dare ignore. Any overseer or foreman who sets foot within the camp to replace Gorthak will feel my wrath!\n\nWe must press our advantage, {name}, and never rest until the Warsong Lumber Camp is a distant memory and a glade of trees stands upon that ground.\n\nNow what was this about explosives...?", objectives = "Slay Overseer Gorthak and any other 12 Horde at the Warsong Lumber Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26458] = { id = 26458, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Falls", description = "Empowered by the ancient rites of the chaotic Old Gods, the members of the Twilight's Hammer strive to bring about the return of their dark patrons and spread death and terror across the world.\n\nWe believe that the Twilight's Hammer has allied with the naga and are amassing in Blackfathom Deeps to the west.\n\nWhatever evil plan brews in the depths of the old temple must be thwarted.\n\nWage war on the Hammer and bring back proof of your deeds. Your efforts will be rewarded handsomely.", objectives = "Bring 10 Twilight Pendants to Sentinel Aluwyn at the Blackfathom Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26459] = { id = 26459, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Researching the Corruption", description = "Foolish blood elves toil with demonic magic. Have they not witnessed what happened with the naga and with the satyrs of Kalimdor?\n\nI fear that the blood elves will meet a similar deformation. Azeroth cannot afford to give birth to another vile race of monsters.\n\nI wish to study the brain stems of the satyr and naga so that I might deduce what fate the sin'dorei are headed toward. In Blackfathom Deeps, just to the west, you will find both satyr and naga.", objectives = "Relwyn Shadestar at the Blackfathom Camp wants 8 Corrupt Brain stems.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26460] = { id = 26460, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Search of Thaelrid", description = "Many rumors circulate these days about the union of the Twilight's Hammer and the naga in Blackfathom Deeps to the west.\n\nMy role here is to collect as much information as I can, so we know when and where help is needed.\n\nIt has been days now since I sent a scout to check on the activity inside Blackfathom Deeps. Scout Thaelrid has not yet reported back.\n\nMy other scouts are preoccupied with pressing matters.\n\nSeek out Thaelrid for me, {name}.", sourceObjective = "Seek out Scout Thaelrid inside Blackfathom Deeps.", sourceObjectiveStatus = "unverified-source-field" }
quests[26461] = { id = 26461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackfathom Villainy", description = "Strength has left me. Your help is needed!\n\nLong ago this site was a great temple of Elune. But misfortune led to ruin when the corruption of an Old God seeped up from below and tainted the sacred moonwell.\n\nAku'Mai, servant of the Old God, rose from the waters.\n\nThe Twilight's Hammer cultists have allied with the naga to occupy these grounds. The cultists, led by Kelris, sacrifice innocents to Aku'Mai for power.\n\nSlay Kelris and bring his head to Ashelan at the Blackfathom Camp, {name}, please.", objectives = "Bring the head of Twilight Lord Kelris to Ashelan Northwood at the Blackfathom Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26462] = { id = 26462, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wicked Revantusk", description = "These Revantusk trolls think they're special for bein' in the Horde. Makes me laugh!\n\nSee, the funny part is, it doesn't matter if they're part of the Horde, or some kinda troll empire, or the bloody Burning Legion for that matter. We've fought trolls in these lands for a few centuries now.\n\nIn fact, I'll be kind enough to let you lend a hand, <lad/lass>! Grab a weapon and head out to the battlefield and help our boys to the east.", completion = "Not bad for a city-dwellin' {race}. Good show, aye!", objectives = "Kill 10 Revantusk Stalkers or Revantusk Hexxers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26463] = { id = 26463, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finding Teronis", description = "A friend of mine from Astranaar, Raene Wolfrunner, asked me to send a scout west to Lake Falathim. Teronis left days ago, just before the Horde attacked.\n\nHe was searching for an item he thought could slow the furbolg attacks on our people--a rod created by a now-dead, evil wizard.\n\nBefore he left, he mentioned a gem for the rod. Unfortunately, we know that the lake has been invaded by some evil force.\n\nPlease, {name}, find my friend.", completion = "Teronis' body lies broken atop the small rise next to the Keeper.\n\nDeep slashes crisscross his corpse.", objectives = "Find Teronis at Lake Falathim in Ashenvale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26464] = { id = 26464, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Gem", description = "As you rummage through Teronis' belongings, you find a water-damaged journal.\n\nQuickly flipping through the last legible pages, you read that Teronis makes mention of finding the gem, but then of having lost it in the Falathim area.\n\nThe only thing left to do is find it. Perhaps the tendrils have it...?", progress = "Ah, welcome back, {name}.", completion = "This is terrible, {name}. Teronis is dead?!\n\nThe time for mourning will come, but for now we must focus our efforts. I will send some of the Sentinels to recover Teronis' body and to assist the keeper.\n\nYou have the gem that Teronis was seeking? It must be delivered to Astranaar.", objectives = "Find the Glowing Gem.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26465] = { id = 26465, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ancient Statuettes", description = "I would charge you with a task, {class}.\n\nI was on my boat, skimming over the submerged ruins of Zoram, when naga attacked me, surging from the water and tearing at me with their claws! I fled and the rest, as they say, is history.\n\nI am an archaeologist of sorts, and I am attempting to recover artifacts of the lost city.\n\nWill you head out onto the Zoram Strand to the southwest and recover any ancient statuettes you come across? They are the reason I have braved the dangers of the Zoram Strand.", progress = "Have you found many statuettes, {name}?", completion = "That's quite a few that you have found! Thank you, {name}!\n\nThe old city of Zoram holds many secrets, and these statuettes may be the key to many of them.", objectives = "Collect 10 Ancient Statuettes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
